        if order is not None:
            params['order'] = order
        if limit is not None:
            params['limit'] = min(limit, 1000)
        if sort is not None:
            params['sort'] = sort
        result = make_polygon_request('/v3/reference/splits', params)
        if 'error' in result:
            return result
        splits = []
