def get_single_ticker_snapshot(ticker: str) -> Dict:
    """
    Retrieve the most recent market data snapshot for a single ticker.
    This endpoint consolidates the latest trade, quote, and aggregated data (minute, day, and previous day)

    Args:
        ticker: Specify a case-sensitive ticker symbol (e.g., AAPL for Apple Inc.)

    Returns:
        Dictionary containing ticker snapshot data or error information
    """
    try:
        result = make_polygon_request(f'/v2/snapshot/locale/us/markets/stocks/tickers/{ticker}', {})
        if 'error' in result:
            return result
        ticker_data = result.get('ticker', {})
        if not ticker_data:
            return {'error': f'No snapshot data found for {ticker}'}
        snapshot_data = {'ticker': ticker_data.get('ticker'), 'updated': ticker_data.get('updated'), 'todays_change': ticker_data.get('todaysChange'), 'todays_change_perc': ticker_data.get('todaysChangePerc'), 'day': {'open': ticker_data.get('day', {}).get('o'), 'high': ticker_data.get('day', {}).get('h'), 'low': ticker_data.get('day', {}).get('l'), 'close': ticker_data.get('day', {}).get('c'), 'volume': ticker_data.get('day', {}).get('v'), 'vwap': ticker_data.get('day', {}).get('vw')}, 'prev_day': {'open': ticker_data.get('prevDay', {}).get('o'), 'high': ticker_data.get('prevDay', {}).get('h'), 'low': ticker_data.get('prevDay', {}).get('l'), 'close': ticker_data.get('prevDay', {}).get('c'), 'volume': ticker_data.get('prevDay', {}).get('v'), 'vwap': ticker_data.get('prevDay', {}).get('vw')}, 'last_trade': {'price': ticker_data.get('lastTrade', {}).get('p'), 'size': ticker_data.get('lastTrade', {}).get('s'), 'timestamp': ticker_data.get('lastTrade', {}).get('t'), 'exchange': ticker_data.get('lastTrade', {}).get('x'), 'conditions': ticker_data.get('lastTrade', {}).get('c')}, 'last_quote': {'bid_price': ticker_data.get('lastQuote', {}).get('P'), 'bid_size': ticker_data.get('lastQuote', {}).get('S'), 'ask_price': ticker_data.get('lastQuote', {}).get('p'), 'ask_size': ticker_data.get('lastQuote', {}).get('s'), 'timestamp': ticker_data.get('lastQuote', {}).get('t'), 'conditions': ticker_data.get('lastQuote', {}).get('c')}, 'minute': {'open': ticker_data.get('min', {}).get('o'), 'high': ticker_data.get('min', {}).get('h'), 'low': ticker_data.get('min', {}).get('l'), 'close': ticker_data.get('min', {}).get('c'), 'volume': ticker_data.get('min', {}).get('v'), 'vwap': ticker_data.get('min', {}).get('vw'), 'num_trades': ticker_data.get('min', {}).get('n'), 'timestamp': ticker_data.get('min', {}).get('t')}}
        return {'success': True, 'snapshot': snapshot_data, 'request_id': result.get('request_id'), 'status': result.get('status')}
    except Exception as e:
        return {'error': str(e), 'function': 'get_single_ticker_snapshot', 'ticker': ticker}

def get_full_market_snapshot(tickers: Optional[List[str]]=None, include_otc: bool=False) -> Dict:
    """
    Get a comprehensive snapshot of the entire U.S. stock market or specific tickers

    Args:
        tickers: List of ticker symbols to get snapshots for (None = all tickers)
        include_otc: Include OTC securities in response

    Returns:
        Full market snapshot with comprehensive data for all requested tickers
    """
    try:
        url = '/v2/snapshot/locale/us/markets/stocks/tickers'
        params = {}
        if tickers:
            params['tickers'] = ','.join(tickers)
        params['include_otc'] = str(include_otc).lower()
        result = make_polygon_request(url, params)
        if 'error' in result:
            return result
        snapshot_data = {'status': result.get('status'), 'count': result.get('count', 0), 'request_id': result.get('requestId'), 'tickers': result.get('tickers', [])}
        tickers_list = snapshot_data['tickers']
        if tickers_list:
            total_volume = sum((ticker.get('day', {}).get('v', 0) for ticker in tickers_list))
            advancers = sum((1 for ticker in tickers_list if ticker.get('todaysChange', 0) > 0))
            decliners = sum((1 for ticker in tickers_list if ticker.get('todaysChange', 0) < 0))
            unchanged = sum((1 for ticker in tickers_list if ticker.get('todaysChange', 0) == 0))
            snapshot_data['summary'] = {'total_volume': total_volume, 'advancers': advancers, 'decliners': decliners, 'unchanged': unchanged, 'total_processed': len(tickers_list)}
        return snapshot_data
    except Exception as e:
        return {'error': f'Failed to get full market snapshot: {str(e)}'}

def get_unified_snapshot(ticker: Optional[str]=None, type: Optional[str]=None, ticker_gte: Optional[str]=None, ticker_gt: Optional[str]=None, ticker_lte: Optional[str]=None, ticker_lt: Optional[str]=None, ticker_any_of: Optional[str]=None, order: Optional[str]=None, limit: Optional[int]=None, sort: Optional[str]=None) -> Dict:
    """
    Retrieve unified snapshots of market data for multiple asset classes including
    stocks, options, forex, and cryptocurrencies in a single request

    Args:
        ticker: Search a range of tickers lexicographically
        type: Query by the type of asset (stocks, options, fx, crypto, indices)
        ticker_gte: Range by ticker (greater than or equal)
        ticker_gt: Range by ticker (greater than)
        ticker_lte: Range by ticker (less than or equal)
        ticker_lt: Range by ticker (less than)
        ticker_any_of: Comma separated list of tickers, up to a maximum of 250
        order: Order results based on the sort field
        limit: Limit the number of results returned (default: 10, max: 250)
        sort: Sort field used for ordering

    Returns:
        Dictionary containing unified snapshot data for multiple asset classes
    """
    try:
        params = {}
        if ticker is not None:
            params['ticker'] = ticker
        if type is not None:
            params['type'] = type
        if ticker_gte is not None:
            params['ticker.gte'] = ticker_gte
        if ticker_gt is not None:
            params['ticker.gt'] = ticker_gt
        if ticker_lte is not None:
            params['ticker.lte'] = ticker_lte
        if ticker_lt is not None:
            params['ticker.lt'] = ticker_lt
        if ticker_any_of is not None:
            params['ticker.any_of'] = ticker_any_of
        if order is not None:
            params['order'] = order
        if limit is not None:
            params['limit'] = min(limit, 250)
        if sort is not None:
            params['sort'] = sort
        result = make_polygon_request('/v3/snapshot', params)
        if 'error' in result:
            return result
        snapshots = []
        for snapshot_data in result.get('results', []):
            snapshot_info = {'ticker': snapshot_data.get('ticker'), 'name': snapshot_data.get('name'), 'type': snapshot_data.get('type'), 'market_status': snapshot_data.get('market_status'), 'timeframe': snapshot_data.get('timeframe'), 'last_updated': snapshot_data.get('last_updated')}
            if snapshot_data.get('error'):
                snapshot_info['error'] = {'code': snapshot_data.get('error'), 'message': snapshot_data.get('message')}
            if snapshot_data.get('fmv') is not None:
                snapshot_info['fair_market_value'] = {'value': snapshot_data.get('fmv'), 'last_updated': snapshot_data.get('fmv_last_updated')}
            session_data = snapshot_data.get('session')
            if session_data:
                snapshot_info['session'] = {'open': session_data.get('open'), 'high': session_data.get('high'), 'low': session_data.get('low'), 'close': session_data.get('close'), 'volume': session_data.get('volume'), 'previous_close': session_data.get('previous_close'), 'change': session_data.get('change'), 'change_percent': session_data.get('change_percent'), 'early_trading_change': session_data.get('early_trading_change'), 'early_trading_change_percent': session_data.get('early_trading_change_percent'), 'regular_trading_change': session_data.get('regular_trading_change'), 'regular_trading_change_percent': session_data.get('regular_trading_change_percent'), 'late_trading_change': session_data.get('late_trading_change'), 'late_trading_change_percent': session_data.get('late_trading_change_percent')}
            last_quote = snapshot_data.get('last_quote')
            if last_quote:
                snapshot_info['last_quote'] = {'bid': last_quote.get('bid'), 'bid_size': last_quote.get('bid_size'), 'bid_exchange': last_quote.get('bid_exchange'), 'ask': last_quote.get('ask'), 'ask_size': last_quote.get('ask_size'), 'ask_exchange': last_quote.get('ask_exchange'), 'midpoint': last_quote.get('midpoint'), 'last_updated': last_quote.get('last_updated'), 'timeframe': last_quote.get('timeframe')}
            last_trade = snapshot_data.get('last_trade')
            if last_trade:
                snapshot_info['last_trade'] = {'price': last_trade.get('price'), 'size': last_trade.get('size'), 'exchange': last_trade.get('exchange'), 'conditions': last_trade.get('conditions'), 'last_updated': last_trade.get('last_updated'), 'sip_timestamp': last_trade.get('sip_timestamp'), 'timeframe': last_trade.get('timeframe')}
            asset_type = snapshot_data.get('type')
            if asset_type == 'stocks':
                last_minute = snapshot_data.get('last_minute')
                if last_minute:
                    snapshot_info['last_minute'] = {'open': last_minute.get('open'), 'high': last_minute.get('high'), 'low': last_minute.get('low'), 'close': last_minute.get('close'), 'volume': last_minute.get('volume'), 'transactions': last_minute.get('transactions'), 'vwap': last_minute.get('vwap')}
            elif asset_type == 'options':
                details = snapshot_data.get('details', {})
                if details:
                    snapshot_info['option_details'] = {'contract_type': details.get('contract_type'), 'exercise_style': details.get('exercise_style'), 'expiration_date': details.get('expiration_date'), 'strike_price': details.get('strike_price'), 'shares_per_contract': details.get('shares_per_contract'), 'underlying_ticker': details.get('underlying_ticker')}
                greeks = snapshot_data.get('greeks', {})
                if greeks:
                    snapshot_info['greeks'] = {'delta': greeks.get('delta'), 'gamma': greeks.get('gamma'), 'theta': greeks.get('theta'), 'vega': greeks.get('vega')}
                snapshot_info['break_even_price'] = snapshot_data.get('break_even_price')
                snapshot_info['implied_volatility'] = snapshot_data.get('implied_volatility')
                snapshot_info['open_interest'] = snapshot_data.get('open_interest')
                underlying = snapshot_data.get('underlying_asset', {})
                if underlying:
                    snapshot_info['underlying_asset'] = {'ticker': underlying.get('ticker'), 'price': underlying.get('price'), 'change_to_break_even': underlying.get('change_to_break_even'), 'last_updated': underlying.get('last_updated'), 'timeframe': underlying.get('timeframe')}
            elif asset_type == 'indices':
                snapshot_info['value'] = snapshot_data.get('value')
            snapshots.append(snapshot_info)
        asset_type_counts = {}
        successful_requests = 0
        failed_requests = 0
        for snapshot in snapshots:
            asset_type = snapshot.get('type', 'unknown')
            asset_type_counts[asset_type] = asset_type_counts.get(asset_type, 0) + 1
            if 'error' in snapshot:
                failed_requests += 1
            else:
                successful_requests += 1
        return {'success': True, 'count': len(snapshots), 'snapshots': snapshots, 'summary': {'asset_types': asset_type_counts, 'successful_requests': successful_requests, 'failed_requests': failed_requests, 'total_processed': len(snapshots)}, 'next_url': result.get('next_url'), 'request_id': result.get('request_id'), 'status': result.get('status')}
    except Exception as e:
        return {'error': f'Failed to get unified snapshot: {str(e)}'}

def get_top_market_movers(direction: str, include_otc: bool=False) -> Dict:
    """
    Retrieve snapshot data highlighting the top 20 gainers or losers in the U.S. stock market

    Args:
        direction: The direction of market movers to return. Must be either 'gainers' or 'losers'
        include_otc: Include OTC securities in response

    Returns:
        Dictionary containing top market movers data
    """
    try:
        if direction.lower() not in ['gainers', 'losers']:
            return {'error': "Direction must be either 'gainers' or 'losers'"}
        url = f'/v2/snapshot/locale/us/markets/stocks/{direction.lower()}'
        params = {}
        params['include_otc'] = str(include_otc).lower()
        result = make_polygon_request(url, params)
        if 'error' in result:
            return result
        tickers_list = result.get('tickers', [])
        enhanced_tickers = []
        for ticker_data in tickers_list:
            enhanced_ticker = {'ticker': ticker_data.get('ticker'), 'updated': ticker_data.get('updated'), 'todays_change': ticker_data.get('todaysChange'), 'todays_change_perc': ticker_data.get('todaysChangePerc'), 'day': {'open': ticker_data.get('day', {}).get('o'), 'high': ticker_data.get('day', {}).get('h'), 'low': ticker_data.get('day', {}).get('l'), 'close': ticker_data.get('day', {}).get('c'), 'volume': ticker_data.get('day', {}).get('v'), 'vwap': ticker_data.get('day', {}).get('vw')}, 'prev_day': {'open': ticker_data.get('prevDay', {}).get('o'), 'high': ticker_data.get('prevDay', {}).get('h'), 'low': ticker_data.get('prevDay', {}).get('l'), 'close': ticker_data.get('prevDay', {}).get('c'), 'volume': ticker_data.get('prevDay', {}).get('v'), 'vwap': ticker_data.get('prevDay', {}).get('vw')}, 'last_trade': {'price': ticker_data.get('lastTrade', {}).get('p'), 'size': ticker_data.get('lastTrade', {}).get('s'), 'timestamp': ticker_data.get('lastTrade', {}).get('t'), 'exchange': ticker_data.get('lastTrade', {}).get('x'), 'conditions': ticker_data.get('lastTrade', {}).get('c')}, 'last_quote': {'bid_price': ticker_data.get('lastQuote', {}).get('P'), 'bid_size': ticker_data.get('lastQuote', {}).get('S'), 'ask_price': ticker_data.get('lastQuote', {}).get('p'), 'ask_size': ticker_data.get('lastQuote', {}).get('s'), 'timestamp': ticker_data.get('lastQuote', {}).get('t'), 'conditions': ticker_data.get('lastQuote', {}).get('c')}, 'minute': {'open': ticker_data.get('min', {}).get('o'), 'high': ticker_data.get('min', {}).get('h'), 'low': ticker_data.get('min', {}).get('l'), 'close': ticker_data.get('min', {}).get('c'), 'volume': ticker_data.get('min', {}).get('v'), 'vwap': ticker_data.get('min', {}).get('vw'), 'num_trades': ticker_data.get('min', {}).get('n'), 'timestamp': ticker_data.get('min', {}).get('t')}}
            day_volume = ticker_data.get('day', {}).get('v', 0)
            prev_close = ticker_data.get('prevDay', {}).get('c', 0)
            current_price = ticker_data.get('day', {}).get('c', 0)
            enhanced_ticker['metrics'] = {'day_volume': day_volume, 'previous_close': prev_close, 'current_price': current_price, 'price_range': ticker_data.get('day', {}).get('h', 0) - ticker_data.get('day', {}).get('l', 0), 'spread': ticker_data.get('lastQuote', {}).get('p', 0) - ticker_data.get('lastQuote', {}).get('P', 0)}
            enhanced_ticker['rank'] = len(enhanced_tickers) + 1
            enhanced_ticker['direction'] = direction.lower()
            enhanced_tickers.append(enhanced_ticker)
        if enhanced_tickers:
            total_volume = sum((ticker['metrics']['day_volume'] for ticker in enhanced_tickers))
            avg_change = sum((ticker['todays_change_perc'] for ticker in enhanced_tickers)) / len(enhanced_tickers)
            biggest_mover = max(enhanced_tickers, key=lambda x: abs(x['todays_change_perc']))
            price_ranges = {'under_10': len([t for t in enhanced_tickers if t['metrics']['current_price'] < 10]), '10_to_50': len([t for t in enhanced_tickers if 10 <= t['metrics']['current_price'] < 50]), '50_to_100': len([t for t in enhanced_tickers if 50 <= t['metrics']['current_price'] < 100]), 'over_100': len([t for t in enhanced_tickers if t['metrics']['current_price'] >= 100])}
            summary = {'direction': direction.lower(), 'total_volume': total_volume, 'average_change_percent': round(avg_change, 2), 'biggest_mover': {'ticker': biggest_mover['ticker'], 'change_percent': biggest_mover['todays_change_perc']}, 'price_distribution': price_ranges, 'movers_count': len(enhanced_tickers), 'include_otc': include_otc}
        else:
            summary = {'direction': direction.lower(), 'movers_count': 0, 'include_otc': include_otc, 'message': f'No top {direction.lower()} found at this time'}
        return {'success': True, 'direction': direction.lower(), 'status': result.get('status'), 'tickers': enhanced_tickers, 'summary': summary, 'request_id': result.get('request_id')}
    except Exception as e:
        return {'error': f'Failed to get top market movers: {str(e)}'}

def get_trades(stock_ticker: str, timestamp: Optional[str]=None, timestamp_gte: Optional[str]=None, timestamp_gt: Optional[str]=None, timestamp_lte: Optional[str]=None, timestamp_lt: Optional[str]=None, order: Optional[str]=None, limit: Optional[int]=None, sort: Optional[str]=None) -> Dict:
    """
    Retrieve comprehensive, tick-level trade data for a specified stock ticker within a defined time range

    Args:
        stock_ticker: Case-sensitive ticker symbol (e.g., AAPL)
        timestamp: Query by trade timestamp. Either a date with the format YYYY-MM-DD or a nanosecond timestamp
        timestamp_gte: Range by timestamp (greater than or equal)
        timestamp_gt: Range by timestamp (greater than)
        timestamp_lte: Range by timestamp (less than or equal)
        timestamp_lt: Range by timestamp (less than)
        order: Order results based on the sort field
        limit: Limit the number of results returned (default: 1000, max: 50000)
        sort: Sort field used for ordering

    Returns:
        Dictionary containing tick-level trade data
    """
    try:
        if not stock_ticker:
            return {'error': 'Stock ticker is required'}
        params = {}
        if timestamp is not None:
            params['timestamp'] = timestamp
        if timestamp_gte is not None:
            params['timestamp.gte'] = timestamp_gte
        if timestamp_gt is not None:
            params['timestamp.gt'] = timestamp_gt
        if timestamp_lte is not None:
            params['timestamp.lte'] = timestamp_lte
        if timestamp_lt is not None:
            params['timestamp.lt'] = timestamp_lt
        if order is not None:
            params['order'] = order
        if limit is not None:
            params['limit'] = min(limit, 50000)
        if sort is not None:
            params['sort'] = sort
        result = make_polygon_request(f'/v3/trades/{stock_ticker}', params)
        if 'error' in result:
            return result
        trades = []
        for trade_data in result.get('results', []):
            trade_info = {'trade_id': trade_data.get('id'), 'ticker': stock_ticker, 'price': trade_data.get('price'), 'size': trade_data.get('size'), 'exchange': trade_data.get('exchange'), 'tape': trade_data.get('tape'), 'sequence_number': trade_data.get('sequence_number'), 'conditions': trade_data.get('conditions', []), 'correction': trade_data.get('correction'), 'trf_id': trade_data.get('trf_id'), 'participant_timestamp': trade_data.get('participant_timestamp'), 'sip_timestamp': trade_data.get('sip_timestamp'), 'trf_timestamp': trade_data.get('trf_timestamp')}
            trade_volume = trade_data.get('size', 0)
            trade_price = trade_data.get('price', 0)
            trade_value = trade_volume * trade_price
            trade_info['metrics'] = {'trade_volume': trade_volume, 'trade_value': trade_value, 'trade_conditions_count': len(trade_data.get('conditions', [])), 'exchange_id': trade_data.get('exchange'), 'tape_id': trade_data.get('tape')}
            tape_map = {1: 'A (NYSE)', 2: 'B (NYSE ARCA)', 3: 'C (NASDAQ)'}
            tape_id = trade_data.get('tape')
            if tape_id in tape_map:
                trade_info['tape_description'] = tape_map[tape_id]
            trades.append(trade_info)
        if trades:
            total_volume = sum((trade['metrics']['trade_volume'] for trade in trades))
            total_value = sum((trade['metrics']['trade_value'] for trade in trades))
            avg_price = sum((trade['price'] for trade in trades)) / len(trades)
            avg_size = total_volume / len(trades)
            prices = [trade['price'] for trade in trades]
            min_price = min(prices)
            max_price = max(prices)
            price_range = max_price - min_price
            exchange_counts = {}
            tape_counts = {}
            for trade in trades:
                exchange = trade['metrics']['exchange_id']
                tape = trade['metrics']['tape_id']
                exchange_counts[exchange] = exchange_counts.get(exchange, 0) + 1
                tape_counts[tape] = tape_counts.get(tape, 0) + 1
            timestamps = [trade['sip_timestamp'] for trade in trades if trade.get('sip_timestamp')]
            if timestamps:
                start_time = min(timestamps)
                end_time = max(timestamps)
                time_range_ns = end_time - start_time
                time_range_seconds = time_range_ns / 1000000000 if time_range_ns > 0 else 0
            else:
                start_time = None
                end_time = None
                time_range_seconds = 0
            summary = {'ticker': stock_ticker, 'trade_count': len(trades), 'total_volume': total_volume, 'total_value': total_value, 'average_price': round(avg_price, 4), 'average_size': round(avg_size, 2), 'min_price': min_price, 'max_price': max_price, 'price_range': round(price_range, 4), 'time_range_seconds': round(time_range_seconds, 3), 'start_time': start_time, 'end_time': end_time, 'exchange_distribution': exchange_counts, 'tape_distribution': tape_counts, 'most_active_exchange': max(exchange_counts.items(), key=lambda x: x[1])[0] if exchange_counts else None}
        else:
            summary = {'ticker': stock_ticker, 'trade_count': 0, 'message': f'No trades found for {stock_ticker} with specified criteria'}
        return {'success': True, 'ticker': stock_ticker, 'trades': trades, 'summary': summary, 'next_url': result.get('next_url'), 'request_id': result.get('request_id'), 'status': result.get('status')}
    except Exception as e:
        return {'error': f'Failed to get trades for {stock_ticker}: {str(e)}'}

def get_last_trade(stocks_ticker: str) -> Dict:
    """
    Retrieve the latest available trade for a specified stock ticker, including details such as price, size, exchange, and timestamp

    Args:
        stocks_ticker: Case-sensitive ticker symbol (e.g., AAPL)

    Returns:
        Dictionary containing the most recent trade data
    """
    try:
        if not stocks_ticker:
            return {'error': 'Stock ticker is required'}
        result = make_polygon_request(f'/v2/last/trade/{stocks_ticker}', {})
        if 'error' in result:
            return result
        trade_data = result.get('results')
        if not trade_data:
            return {'error': f'No last trade data found for {stocks_ticker}'}
        last_trade = {'ticker': trade_data.get('T'), 'trade_id': trade_data.get('i'), 'price': trade_data.get('p'), 'size': trade_data.get('s'), 'exchange_id': trade_data.get('x'), 'tape_id': trade_data.get('z'), 'sequence_number': trade_data.get('q'), 'conditions': trade_data.get('c', []), 'correction_indicator': trade_data.get('e'), 'trf_id': trade_data.get('r'), 'sip_timestamp': trade_data.get('t'), 'trf_timestamp': trade_data.get('f'), 'participant_timestamp': trade_data.get('y')}
        tape_map = {1: 'A (NYSE)', 2: 'B (NYSE ARCA)', 3: 'C (NASDAQ)'}
        tape_id = trade_data.get('z')
        if tape_id in tape_map:
            last_trade['tape_description'] = tape_map[tape_id]
        trade_price = trade_data.get('p', 0)
        trade_size = trade_data.get('s', 0)
        trade_value = trade_price * trade_size
        last_trade['metrics'] = {'trade_value': trade_value, 'trade_conditions_count': len(trade_data.get('c', [])), 'exchange_id': trade_data.get('x'), 'tape_id': trade_data.get('z'), 'trf_id': trade_data.get('r')}
        sip_timestamp = trade_data.get('t')
        participant_timestamp = trade_data.get('y')
        trf_timestamp = trade_data.get('f')
        timestamp_analysis = {}
        if sip_timestamp and participant_timestamp:
            latency_sip_participant = sip_timestamp - participant_timestamp
            timestamp_analysis['sip_to_participant_latency_ns'] = latency_sip_participant
            timestamp_analysis['sip_to_participant_latency_ms'] = latency_sip_participant / 1000000
        if trf_timestamp and sip_timestamp:
            latency_trf_sip = sip_timestamp - trf_timestamp
            timestamp_analysis['trf_to_sip_latency_ns'] = latency_trf_sip
            timestamp_analysis['trf_to_sip_latency_ms'] = latency_trf_sip / 1000000
        if participant_timestamp and trf_timestamp:
            latency_participant_trf = participant_timestamp - trf_timestamp
            timestamp_analysis['participant_to_trf_latency_ns'] = latency_participant_trf
            timestamp_analysis['participant_to_trf_latency_ms'] = latency_participant_trf / 1000000
        last_trade['timestamp_analysis'] = timestamp_analysis
        conditions = trade_data.get('c', [])
        if conditions:
            last_trade['conditions_info'] = {'condition_codes': conditions, 'conditions_count': len(conditions), 'has_conditions': True}
        else:
            last_trade['conditions_info'] = {'condition_codes': [], 'conditions_count': 0, 'has_conditions': False}
        last_trade['exchange_info'] = {'exchange_id': trade_data.get('x'), 'is_regular_hours': True, 'tape_id': tape_id, 'tape_description': last_trade.get('tape_description')}
        if sip_timestamp:
            try:
                import datetime
                trade_time = datetime.datetime.fromtimestamp(sip_timestamp / 1000000000)
                last_trade['trade_time_formatted'] = trade_time.strftime('%Y-%m-%d %H:%M:%S.%f')[:-3]
                last_trade['trade_date'] = trade_time.strftime('%Y-%m-%d')
                last_trade['trade_time'] = trade_time.strftime('%H:%M:%S')
            except (ValueError, OSError):
                pass
        return {'success': True, 'ticker': stocks_ticker, 'last_trade': last_trade, 'request_id': result.get('request_id'), 'status': result.get('status')}
    except Exception as e:
        return {'error': f'Failed to get last trade for {stocks_ticker}: {str(e)}'}

def get_quotes(stock_ticker: str, timestamp: Optional[str]=None, timestamp_gte: Optional[str]=None, timestamp_gt: Optional[str]=None, timestamp_lte: Optional[str]=None, timestamp_lt: Optional[str]=None, order: Optional[str]=None, limit: Optional[int]=None, sort: Optional[str]=None) -> Dict:
    """
    Retrieve National Best Bid and Offer (NBBO) quotes for a specified stock ticker over a defined time range

    Args:
        stock_ticker: Case-sensitive ticker symbol (e.g., AAPL)
        timestamp: Query by timestamp. Either a date with the format YYYY-MM-DD or a nanosecond timestamp
        timestamp_gte: Range by timestamp (greater than or equal)
        timestamp_gt: Range by timestamp (greater than)
        timestamp_lte: Range by timestamp (less than or equal)
        timestamp_lt: Range by timestamp (less than)
        order: Order results based on the sort field
        limit: Limit the number of results returned (default: 1000, max: 50000)
        sort: Sort field used for ordering

    Returns:
        Dictionary containing NBBO quote data
    """
    try:
        if not stock_ticker:
            return {'error': 'Stock ticker is required'}
        params = {}
        if timestamp is not None:
            params['timestamp'] = timestamp
        if timestamp_gte is not None:
            params['timestamp.gte'] = timestamp_gte
        if timestamp_gt is not None:
            params['timestamp.gt'] = timestamp_gt
        if timestamp_lte is not None:
            params['timestamp.lte'] = timestamp_lte
        if timestamp_lt is not None:
            params['timestamp.lt'] = timestamp_lt
        if order is not None:
            params['order'] = order
        if limit is not None:
            params['limit'] = min(limit, 50000)
        if sort is not None:
            params['sort'] = sort
        result = make_polygon_request(f'/v3/quotes/{stock_ticker}', params)
        if 'error' in result:
            return result
        quotes = []
        for quote_data in result.get('results', []):
            quote_info = {'ticker': stock_ticker, 'bid_price': quote_data.get('bid_price'), 'bid_size': quote_data.get('bid_size'), 'bid_exchange': quote_data.get('bid_exchange'), 'ask_price': quote_data.get('ask_price'), 'ask_size': quote_data.get('ask_size'), 'ask_exchange': quote_data.get('ask_exchange'), 'tape': quote_data.get('tape'), 'sequence_number': quote_data.get('sequence_number'), 'conditions': quote_data.get('conditions', []), 'indicators': quote_data.get('indicators', []), 'participant_timestamp': quote_data.get('participant_timestamp'), 'sip_timestamp': quote_data.get('sip_timestamp'), 'trf_timestamp': quote_data.get('trf_timestamp')}
            bid_price = quote_data.get('bid_price', 0)
            ask_price = quote_data.get('ask_price', 0)
            bid_size = quote_data.get('bid_size', 0)
            ask_size = quote_data.get('ask_size', 0)
            if bid_price > 0 and ask_price > 0:
                spread = ask_price - bid_price
                spread_percentage = spread / bid_price * 100
                mid_price = (bid_price + ask_price) / 2
            else:
                spread = 0
                spread_percentage = 0
                mid_price = 0
            actual_bid_size = bid_size * 100
            actual_ask_size = ask_size * 100
            quote_info['nbbo_metrics'] = {'spread': spread, 'spread_percentage': round(spread_percentage, 4), 'mid_price': mid_price, 'bid_price': bid_price, 'ask_price': ask_price, 'bid_size_round_lots': bid_size, 'ask_size_round_lots': ask_size, 'bid_size_shares': actual_bid_size, 'ask_size_shares': actual_ask_size, 'total_liquidity_shares': actual_bid_size + actual_ask_size, 'has_bid': bid_price > 0, 'has_ask': ask_price > 0, 'has_nbbo': bid_price > 0 and ask_price > 0}
            quote_info['exchange_info'] = {'bid_exchange_id': quote_data.get('bid_exchange'), 'ask_exchange_id': quote_data.get('ask_exchange'), 'tape_id': quote_data.get('tape'), 'same_exchange': quote_data.get('bid_exchange') == quote_data.get('ask_exchange')}
            tape_map = {1: 'A (NYSE)', 2: 'B (NYSE ARCA)', 3: 'C (NASDAQ)'}
            tape_id = quote_data.get('tape')
            if tape_id in tape_map:
                quote_info['tape_description'] = tape_map[tape_id]
            conditions = quote_data.get('conditions', [])
            indicators = quote_data.get('indicators', [])
            quote_info['quote_conditions'] = {'condition_codes': conditions, 'indicators': indicators, 'conditions_count': len(conditions), 'indicators_count': len(indicators), 'has_conditions': len(conditions) > 0, 'has_indicators': len(indicators) > 0}
            quotes.append(quote_info)
        if quotes:
            spreads = [q['nbbo_metrics']['spread'] for q in quotes if q['nbbo_metrics']['has_nbbo']]
            avg_spread = sum(spreads) / len(spreads) if spreads else 0
            min_spread = min(spreads) if spreads else 0
            max_spread = max(spreads) if spreads else 0
            total_liquidity = sum((q['nbbo_metrics']['total_liquidity_shares'] for q in quotes))
            avg_liquidity = total_liquidity / len(quotes)
            mid_prices = [q['nbbo_metrics']['mid_price'] for q in quotes if q['nbbo_metrics']['mid_price'] > 0]
            avg_mid_price = sum(mid_prices) / len(mid_prices) if mid_prices else 0
            bid_exchanges = {}
            ask_exchanges = {}
            for quote in quotes:
                bid_ex = quote['exchange_info']['bid_exchange_id']
                ask_ex = quote['exchange_info']['ask_exchange_id']
                if bid_ex:
                    bid_exchanges[bid_ex] = bid_exchanges.get(bid_ex, 0) + 1
                if ask_ex:
                    ask_exchanges[ask_ex] = ask_exchanges.get(ask_ex, 0) + 1
            nbbo_complete = sum((1 for q in quotes if q['nbbo_metrics']['has_nbbo']))
            bid_only = sum((1 for q in quotes if q['nbbo_metrics']['has_bid'] and (not q['nbbo_metrics']['has_ask'])))
            ask_only = sum((1 for q in quotes if q['nbbo_metrics']['has_ask'] and (not q['nbbo_metrics']['has_bid'])))
            timestamps = [quote['sip_timestamp'] for quote in quotes if quote.get('sip_timestamp')]
            if timestamps:
                start_time = min(timestamps)
                end_time = max(timestamps)
                time_range_ns = end_time - start_time
                time_range_seconds = time_range_ns / 1000000000 if time_range_ns > 0 else 0
            else:
                start_time = None
                end_time = None
                time_range_seconds = 0
            summary = {'ticker': stock_ticker, 'quote_count': len(quotes), 'time_range_seconds': round(time_range_seconds, 3), 'start_time': start_time, 'end_time': end_time, 'spread_analysis': {'average_spread': round(avg_spread, 4), 'min_spread': min_spread, 'max_spread': max_spread}, 'liquidity_analysis': {'total_liquidity_shares': total_liquidity, 'average_liquidity_shares': round(avg_liquidity, 2)}, 'price_analysis': {'average_mid_price': round(avg_mid_price, 4)}, 'nbbo_completeness': {'complete_nbbo': nbbo_complete, 'bid_only': bid_only, 'ask_only': ask_only, 'nbbo_completion_rate': round(nbbo_complete / len(quotes) * 100, 2)}, 'exchange_distribution': {'bid_exchanges': bid_exchanges, 'ask_exchanges': ask_exchanges, 'most_active_bid_exchange': max(bid_exchanges.items(), key=lambda x: x[1])[0] if bid_exchanges else None, 'most_active_ask_exchange': max(ask_exchanges.items(), key=lambda x: x[1])[0] if ask_exchanges else None}}
        else:
            summary = {'ticker': stock_ticker, 'quote_count': 0, 'message': f'No quotes found for {stock_ticker} with specified criteria'}
        return {'success': True, 'ticker': stock_ticker, 'quotes': quotes, 'summary': summary, 'next_url': result.get('next_url'), 'request_id': result.get('request_id'), 'status': result.get('status')}
    except Exception as e:
        return {'error': f'Failed to get quotes for {stock_ticker}: {str(e)}'}

def get_last_quote(stocks_ticker: str) -> Dict:
    """
    Retrieve the most recent National Best Bid and Offer (NBBO) quote for a specified stock ticker

    Args:
        stocks_ticker: Case-sensitive ticker symbol (e.g., AAPL)

    Returns:
        Dictionary containing the most recent NBBO quote data
    """
    try:
        if not stocks_ticker:
            return {'error': 'Stock ticker is required'}
        result = make_polygon_request(f'/v2/last/nbbo/{stocks_ticker}', {})
        if 'error' in result:
            return result
        quote_data = result.get('results')
        if not quote_data:
            return {'error': f'No last quote data found for {stocks_ticker}'}
        bid_price = quote_data.get('p', 0)
        ask_price = quote_data.get('P', 0)
        bid_size = quote_data.get('s', 0)
        ask_size = quote_data.get('S', 0)
        last_quote = {'ticker': quote_data.get('T'), 'bid_price': bid_price, 'ask_price': ask_price, 'bid_size': bid_size, 'ask_size': ask_size, 'bid_exchange_id': quote_data.get('x'), 'ask_exchange_id': quote_data.get('X'), 'tape_id': quote_data.get('z'), 'sequence_number': quote_data.get('q'), 'conditions': quote_data.get('c', []), 'indicators': quote_data.get('i', []), 'sip_timestamp': quote_data.get('t'), 'trf_timestamp': quote_data.get('f'), 'participant_timestamp': quote_data.get('y')}
        tape_map = {1: 'A (NYSE)', 2: 'B (NYSE ARCA)', 3: 'C (NASDAQ)'}
        tape_id = quote_data.get('z')
        if tape_id in tape_map:
            last_quote['tape_description'] = tape_map[tape_id]
        if bid_price > 0 and ask_price > 0:
            spread = ask_price - bid_price
            spread_percentage = spread / bid_price * 100
            mid_price = (bid_price + ask_price) / 2
        else:
            spread = 0
            spread_percentage = 0
            mid_price = 0
        actual_bid_size = bid_size * 100
        actual_ask_size = ask_size * 100
        last_quote['nbbo_metrics'] = {'spread': spread, 'spread_percentage': round(spread_percentage, 4), 'mid_price': mid_price, 'bid_price': bid_price, 'ask_price': ask_price, 'bid_size_round_lots': bid_size, 'ask_size_round_lots': ask_size, 'bid_size_shares': actual_bid_size, 'ask_size_shares': actual_ask_size, 'total_liquidity_shares': actual_bid_size + actual_ask_size, 'has_bid': bid_price > 0, 'has_ask': ask_price > 0, 'has_nbbo': bid_price > 0 and ask_price > 0, 'spread_bps': round(spread_percentage * 100, 2)}
        last_quote['exchange_info'] = {'bid_exchange_id': quote_data.get('x'), 'ask_exchange_id': quote_data.get('X'), 'tape_id': tape_id, 'same_exchange': quote_data.get('x') == quote_data.get('X'), 'cross_exchange': quote_data.get('x') != quote_data.get('X')}
        sip_timestamp = quote_data.get('t')
        participant_timestamp = quote_data.get('y')
        trf_timestamp = quote_data.get('f')
        timestamp_analysis = {}
        if sip_timestamp and participant_timestamp:
            latency_sip_participant = sip_timestamp - participant_timestamp
            timestamp_analysis['sip_to_participant_latency_ns'] = latency_sip_participant
            timestamp_analysis['sip_to_participant_latency_ms'] = latency_sip_participant / 1000000
        if trf_timestamp and sip_timestamp:
            latency_trf_sip = sip_timestamp - trf_timestamp
            timestamp_analysis['trf_to_sip_latency_ns'] = latency_trf_sip
            timestamp_analysis['trf_to_sip_latency_ms'] = latency_trf_sip / 1000000
        if participant_timestamp and trf_timestamp:
            latency_participant_trf = participant_timestamp - trf_timestamp
            timestamp_analysis['participant_to_trf_latency_ns'] = latency_participant_trf
            timestamp_analysis['participant_to_trf_latency_ms'] = latency_participant_trf / 1000000
        last_quote['timestamp_analysis'] = timestamp_analysis
        conditions = quote_data.get('c', [])
        indicators = quote_data.get('i', [])
        last_quote['quote_conditions'] = {'condition_codes': conditions, 'indicators': indicators, 'conditions_count': len(conditions), 'indicators_count': len(indicators), 'has_conditions': len(conditions) > 0, 'has_indicators': len(indicators) > 0}
        if sip_timestamp:
            try:
                import datetime
                quote_time = datetime.datetime.fromtimestamp(sip_timestamp / 1000000000)
                last_quote['quote_time_formatted'] = quote_time.strftime('%Y-%m-%d %H:%M:%S.%f')[:-3]
                last_quote['quote_date'] = quote_time.strftime('%Y-%m-%d')
                last_quote['quote_time'] = quote_time.strftime('%H:%M:%S')
            except (ValueError, OSError):
                pass
        if last_quote['nbbo_metrics']['has_nbbo']:
            spread_quality = 'Tight' if spread_percentage < 0.1 else 'Normal' if spread_percentage < 0.5 else 'Wide'
            size_quality = 'High' if actual_bid_size + actual_ask_size >= 1000 else 'Normal' if actual_bid_size + actual_ask_size >= 100 else 'Low'
            last_quote['liquidity_analysis'] = {'spread_quality': spread_quality, 'size_quality': size_quality, 'overall_liquidity': 'Excellent' if spread_quality == 'Tight' and size_quality == 'High' else 'Good' if spread_quality in ['Tight', 'Normal'] and size_quality in ['High', 'Normal'] else 'Fair'}
        return {'success': True, 'ticker': stocks_ticker, 'last_quote': last_quote, 'request_id': result.get('request_id'), 'status': result.get('status')}
    except Exception as e:
        return {'error': f'Failed to get last quote for {stocks_ticker}: {str(e)}'}

def get_sma(stock_ticker: str, timestamp: Optional[str]=None, timespan: Optional[str]=None, adjusted: Optional[bool]=None, window: Optional[int]=None, series_type: Optional[str]=None, expand_underlying: Optional[bool]=None, order: Optional[str]=None, limit: Optional[int]=None, timestamp_gte: Optional[str]=None, timestamp_gt: Optional[str]=None, timestamp_lte: Optional[str]=None, timestamp_lt: Optional[str]=None) -> Dict:
    """
    Retrieve the Simple Moving Average (SMA) for a specified ticker over a defined time range

    Args:
        stock_ticker: Case-sensitive ticker symbol (e.g., AAPL)
        timestamp: Query by timestamp. Either a date with the format YYYY-MM-DD or a millisecond timestamp
        timespan: The size of the aggregate time window (e.g., day, hour, minute)
        adjusted: Whether aggregates are adjusted for splits (default: true)
        window: The window size used to calculate SMA (e.g., 10 for 10-day SMA)
        series_type: The price type used for calculation (e.g., close, open, high, low)
        expand_underlying: Whether to include underlying aggregates in response
        order: Order results by timestamp (asc, desc)
        limit: Limit number of results (default: 10, max: 5000)
        timestamp_gte: Range by timestamp (greater than or equal)
        timestamp_gt: Range by timestamp (greater than)
        timestamp_lte: Range by timestamp (less than or equal)
        timestamp_lt: Range by timestamp (less than)

    Returns:
        Dictionary containing SMA indicator data
    """
    try:
        if not stock_ticker:
            return {'error': 'Stock ticker is required'}
        params = {}
        if timestamp is not None:
            params['timestamp'] = timestamp
        if timespan is not None:
            params['timespan'] = timespan
        if adjusted is not None:
            params['adjusted'] = str(adjusted).lower()
        if window is not None:
            params['window'] = window
        if series_type is not None:
            params['series_type'] = series_type
        if expand_underlying is not None:
            params['expand_underlying'] = str(expand_underlying).lower()
        if order is not None:
            params['order'] = order
        if limit is not None:
            params['limit'] = min(limit, 5000)
        if timestamp_gte is not None:
            params['timestamp.gte'] = timestamp_gte
        if timestamp_gt is not None:
            params['timestamp.gt'] = timestamp_gt
        if timestamp_lte is not None:
            params['timestamp.lte'] = timestamp_lte
        if timestamp_lt is not None:
            params['timestamp.lt'] = timestamp_lt
        result = make_polygon_request(f'/v1/indicators/sma/{stock_ticker}', params)
        if 'error' in result:
            return result
        results_data = result.get('results', {})
        if not results_data:
            return {'error': f'No SMA data found for {stock_ticker}'}
        sma_values = results_data.get('values', [])
        underlying_data = results_data.get('underlying', {})
        processed_sma = []
        for sma_point in sma_values:
            point_info = {'timestamp': sma_point.get('timestamp'), 'sma_value': sma_point.get('value'), 'date': None}
            timestamp = sma_point.get('timestamp')
            if timestamp:
                try:
                    import datetime
                    if timestamp > 1000000000000000.0:
                        point_time = datetime.datetime.fromtimestamp(timestamp / 1000000000)
                    else:
                        point_time = datetime.datetime.fromtimestamp(timestamp / 1000)
                    point_info['date'] = point_time.strftime('%Y-%m-%d')
                    point_info['datetime'] = point_time.strftime('%Y-%m-%d %H:%M:%S')
                except (ValueError, OSError):
                    pass
            processed_sma.append(point_info)
        underlying_aggregates = []
        if underlying_data and expand_underlying:
            aggregates = underlying_data.get('aggregates', [])
            for agg in aggregates:
                agg_info = {'timestamp': agg.get('t'), 'open': agg.get('o'), 'high': agg.get('h'), 'low': agg.get('l'), 'close': agg.get('c'), 'volume': agg.get('v'), 'vwap': agg.get('vw'), 'transactions': agg.get('n'), 'date': None}
                timestamp = agg.get('t')
                if timestamp:
                    try:
                        import datetime
                        if timestamp > 1000000000000000.0:
                            agg_time = datetime.datetime.fromtimestamp(timestamp / 1000000000)
                        else:
                            agg_time = datetime.datetime.fromtimestamp(timestamp / 1000)
                        agg_info['date'] = agg_time.strftime('%Y-%m-%d')
                        agg_info['datetime'] = agg_time.strftime('%Y-%m-%d %H:%M:%S')
                    except (ValueError, OSError):
                        pass
                underlying_aggregates.append(agg_info)
        if processed_sma:
            sma_values_list = [point['sma_value'] for point in processed_sma if point['sma_value'] is not None]
            if sma_values_list:
                sma_stats = {'count': len(sma_values_list), 'min_value': min(sma_values_list), 'max_value': max(sma_values_list), 'avg_value': sum(sma_values_list) / len(sma_values_list), 'latest_value': sma_values_list[-1] if sma_values_list else None, 'first_value': sma_values_list[0] if sma_values_list else None, 'total_change': sma_values_list[-1] - sma_values_list[0] if len(sma_values_list) > 1 else 0, 'percent_change': (sma_values_list[-1] - sma_values_list[0]) / sma_values_list[0] * 100 if len(sma_values_list) > 1 and sma_values_list[0] != 0 else 0}
            else:
                sma_stats = {'count': 0, 'message': 'No valid SMA values found'}
        else:
            sma_stats = {'count': 0, 'message': 'No SMA data found'}
        sma_response = {'ticker': stock_ticker, 'indicator_type': 'SMA', 'parameters': {'window': window, 'series_type': series_type, 'timespan': timespan, 'adjusted': adjusted}, 'sma_values': processed_sma, 'statistics': sma_stats, 'underlying_url': underlying_data.get('url') if underlying_data else None}
        if expand_underlying and underlying_aggregates:
            sma_response['underlying_aggregates'] = underlying_aggregates
        return {'success': True, 'sma_data': sma_response, 'next_url': result.get('next_url'), 'request_id': result.get('request_id'), 'status': result.get('status')}
    except Exception as e:
        return {'error': f'Failed to get SMA for {stock_ticker}: {str(e)}'}

