class InvestorClassification:
    """Classification and characteristics of different investor types"""
    INVESTOR_CHARACTERISTICS = {InvestorType.INDIVIDUAL: {'typical_objectives': [InvestmentObjective.CAPITAL_APPRECIATION, InvestmentObjective.TOTAL_RETURN], 'time_horizon': 'Variable (accumulation to spending phase)', 'liquidity_needs': 'Generally high', 'tax_considerations': 'Highly relevant', 'regulatory_constraints': 'Minimal', 'risk_tolerance': 'Wide range', 'typical_constraints': ['Behavioral biases', 'Limited investment knowledge', 'Tax implications']}, InvestorType.PENSION_FUND: {'typical_objectives': [InvestmentObjective.TOTAL_RETURN], 'time_horizon': 'Long-term', 'liquidity_needs': 'Predictable cash flows', 'tax_considerations': 'Often tax-exempt', 'regulatory_constraints': 'ERISA and other regulations', 'risk_tolerance': 'Moderate to high', 'typical_constraints': ['Regulatory limits', 'Liability matching', 'Funding ratio considerations']}, InvestorType.ENDOWMENT: {'typical_objectives': [InvestmentObjective.TOTAL_RETURN], 'time_horizon': 'Perpetual', 'liquidity_needs': 'Annual spending requirements', 'tax_considerations': 'Tax-exempt', 'regulatory_constraints': 'UPMIFA and state regulations', 'risk_tolerance': 'High', 'typical_constraints': ['Spending policy', 'Intergenerational equity', 'Mission alignment']}, InvestorType.INSURANCE_COMPANY: {'typical_objectives': [InvestmentObjective.CURRENT_INCOME], 'time_horizon': 'Liability-driven', 'liquidity_needs': 'Claims-driven', 'tax_considerations': 'Corporate tax rates', 'regulatory_constraints': 'Insurance regulations', 'risk_tolerance': 'Conservative', 'typical_constraints': ['Asset-liability matching', 'Regulatory capital', 'Credit quality requirements']}}

    @classmethod
    def get_investor_characteristics(cls, investor_type: InvestorType) -> Dict:
        """Get characteristics for specific investor type"""
        return cls.INVESTOR_CHARACTERISTICS.get(investor_type, {})

    @classmethod
    def compare_investor_types(cls, investor_types: List[InvestorType]) -> Dict:
        """Compare characteristics across investor types"""
        comparison = {}
        for investor_type in investor_types:
            comparison[investor_type.value] = cls.get_investor_characteristics(investor_type)
        return comparison

    @classmethod
    def lifecycle_analysis(cls, current_stage: LifecycleStage, age: int, financial_situation: Dict) -> Dict:
        """Analyze individual investor lifecycle stage"""
        lifecycle_characteristics = {LifecycleStage.ACCUMULATION: {'typical_age_range': '20-45', 'primary_objective': InvestmentObjective.CAPITAL_APPRECIATION, 'risk_tolerance': 'High', 'time_horizon': 'Long', 'liquidity_needs': 'Low', 'investment_focus': 'Growth assets, tax-deferred savings'}, LifecycleStage.CONSOLIDATION: {'typical_age_range': '45-60', 'primary_objective': InvestmentObjective.TOTAL_RETURN, 'risk_tolerance': 'Moderate to High', 'time_horizon': 'Medium to Long', 'liquidity_needs': 'Moderate', 'investment_focus': 'Balanced approach, retirement planning'}, LifecycleStage.SPENDING: {'typical_age_range': '60+', 'primary_objective': InvestmentObjective.CURRENT_INCOME, 'risk_tolerance': 'Conservative to Moderate', 'time_horizon': 'Medium', 'liquidity_needs': 'High', 'investment_focus': 'Income generation, capital preservation'}, LifecycleStage.GIFTING: {'typical_age_range': '65+', 'primary_objective': InvestmentObjective.CAPITAL_APPRECIATION, 'risk_tolerance': 'Varies', 'time_horizon': 'Long (for beneficiaries)', 'liquidity_needs': 'Low', 'investment_focus': 'Growth for next generation, tax efficiency'}}
        stage_characteristics = lifecycle_characteristics[current_stage]
        customizations = {}
        if current_stage == LifecycleStage.ACCUMULATION and age > 40:
            customizations['approaching_consolidation'] = True
        elif current_stage == LifecycleStage.CONSOLIDATION and age > 55:
            customizations['approaching_spending'] = True
        if financial_situation.get('wealth_level') == 'high':
            customizations['higher_risk_capacity'] = True
        if financial_situation.get('income_stability') == 'low':
            customizations['increased_liquidity_needs'] = True
        return {'current_stage': current_stage.value, 'stage_characteristics': stage_characteristics, 'customizations': customizations, 'transition_considerations': cls._analyze_transition_needs(current_stage, age, financial_situation)}

    @classmethod
    def _analyze_transition_needs(cls, current_stage: LifecycleStage, age: int, financial_situation: Dict) -> Dict:
        """Analyze needs for transitioning between lifecycle stages"""
        transitions = {}
        if current_stage == LifecycleStage.ACCUMULATION:
            years_to_consolidation = max(0, 45 - age)
            transitions['to_consolidation'] = {'estimated_years': years_to_consolidation, 'preparation_needed': years_to_consolidation <= 5, 'key_actions': ['Increase savings rate', 'Diversify investments', 'Review risk tolerance']}
        elif current_stage == LifecycleStage.CONSOLIDATION:
            years_to_spending = max(0, 65 - age)
            transitions['to_spending'] = {'estimated_years': years_to_spending, 'preparation_needed': years_to_spending <= 10, 'key_actions': ['Retirement planning', 'Income replacement strategy', 'Healthcare planning']}
        return transitions

@classmethod
def _analyze_transition_needs(cls, current_stage: LifecycleStage, age: int, financial_situation: Dict) -> Dict:
    """Analyze needs for transitioning between lifecycle stages"""
    transitions = {}
    if current_stage == LifecycleStage.ACCUMULATION:
        years_to_consolidation = max(0, 45 - age)
        transitions['to_consolidation'] = {'estimated_years': years_to_consolidation, 'preparation_needed': years_to_consolidation <= 5, 'key_actions': ['Increase savings rate', 'Diversify investments', 'Review risk tolerance']}
    elif current_stage == LifecycleStage.CONSOLIDATION:
        years_to_spending = max(0, 65 - age)
        transitions['to_spending'] = {'estimated_years': years_to_spending, 'preparation_needed': years_to_spending <= 10, 'key_actions': ['Retirement planning', 'Income replacement strategy', 'Healthcare planning']}
    return transitions

class PensionPlans:
    """Defined Contribution and Defined Benefit pension plan analysis"""

    @staticmethod
    def defined_contribution_analysis() -> Dict:
        """Analyze DC plan characteristics and investment implications"""
        return {'plan_structure': {'contribution_mechanism': 'Employee and/or employer contributions to individual accounts', 'investment_responsibility': 'Participant bears investment risk and makes investment decisions', 'benefit_determination': 'Benefits based on account balance at retirement', 'portability': 'High - account follows employee'}, 'investment_characteristics': {'investment_options': 'Typically limited menu of mutual funds', 'asset_allocation_responsibility': 'Participant responsibility', 'lifecycle_funds': 'Target-date funds increasingly popular', 'default_options': 'QDIA (Qualified Default Investment Alternative) required'}, 'risk_factors': {'investment_risk': 'Borne entirely by participant', 'longevity_risk': 'Participant bears risk of outliving assets', 'inflation_risk': 'No automatic inflation protection', 'timing_risk': 'Market conditions at retirement impact benefits'}, 'advantages': ['Portable across employers', 'Individual control over investments', 'Potential for higher returns', 'Transparent account values'], 'disadvantages': ['Investment risk on participant', 'No guaranteed income', 'Requires investment knowledge', 'Vulnerable to market timing']}

    @staticmethod
    def defined_benefit_analysis() -> Dict:
        """Analyze DB plan characteristics and investment implications"""
        return {'plan_structure': {'benefit_formula': 'Predetermined formula based on salary and service', 'investment_responsibility': 'Plan sponsor bears investment risk', 'benefit_determination': 'Formula-driven, typically lifetime annuity', 'portability': 'Limited - benefits tied to specific employer'}, 'investment_characteristics': {'asset_allocation': 'Professional management by plan sponsor', 'liability_driven_investing': 'Assets managed to meet future liabilities', 'sophisticated_strategies': 'Access to alternative investments and advanced strategies', 'actuarial_assumptions': 'Investment returns assumed in actuarial valuations'}, 'risk_factors': {'sponsor_risk': "Plan dependent on employer's financial health", 'underfunding_risk': 'Plans may become underfunded', 'regulatory_risk': 'Subject to changing regulations', 'interest_rate_risk': 'Liability values sensitive to interest rate changes'}, 'advantages': ['Guaranteed retirement income', 'Professional investment management', 'Pooled longevity risk', 'Inflation protection (some plans)'], 'disadvantages': ['Limited portability', 'Dependent on employer viability', 'Declining availability', 'Complex regulations']}

    @staticmethod
    def compare_dc_vs_db(participant_profile: Dict) -> Dict:
        """Compare DC vs DB plans for specific participant profile"""
        age = participant_profile.get('age', 35)
        income = participant_profile.get('income', 50000)
        job_mobility = participant_profile.get('job_mobility', 'moderate')
        investment_knowledge = participant_profile.get('investment_knowledge', 'moderate')
        comparison = {'better_for_participant': None, 'dc_advantages_for_this_profile': [], 'db_advantages_for_this_profile': [], 'recommendations': []}
        if age < 30:
            comparison['dc_advantages_for_this_profile'].append('Long time horizon allows for growth investing')
            comparison['dc_advantages_for_this_profile'].append('High portability valuable for career mobility')
        elif age > 50:
            comparison['db_advantages_for_this_profile'].append('Guaranteed income reduces late-career risk')
            comparison['db_advantages_for_this_profile'].append('Professional management valuable near retirement')
        if job_mobility == 'high':
            comparison['dc_advantages_for_this_profile'].append('Portability essential for mobile workers')
        elif job_mobility == 'low':
            comparison['db_advantages_for_this_profile'].append('Long tenure maximizes DB benefits')
        if investment_knowledge == 'low':
            comparison['db_advantages_for_this_profile'].append('Professional management compensates for lack of knowledge')
            comparison['recommendations'].append('If DC only, consider target-date funds')
        elif investment_knowledge == 'high':
            comparison['dc_advantages_for_this_profile'].append('Can potentially outperform through active management')
        dc_score = len(comparison['dc_advantages_for_this_profile'])
        db_score = len(comparison['db_advantages_for_this_profile'])
        if dc_score > db_score:
            comparison['better_for_participant'] = 'DC Plan'
        elif db_score > dc_score:
            comparison['better_for_participant'] = 'DB Plan'
        else:
            comparison['better_for_participant'] = 'Both have merit'
        return comparison

