class MultifactorModels:
    """Multifactor models implementation and analysis"""

    @staticmethod
    def arbitrage_pricing_theory_analysis() -> Dict:
        """Analyze Arbitrage Pricing Theory and its assumptions"""
        return {'apt_assumptions': {'factor_model': 'Returns generated by linear factor model', 'diversification': 'Unsystematic risk can be diversified away', 'no_arbitrage': 'No arbitrage opportunities exist in equilibrium', 'competitive_markets': 'Markets are competitive with rational investors'}, 'apt_equation': {'mathematical_form': 'E(Ri) = λ0 + λ1*βi1 + λ2*βi2 + ... + λk*βik', 'components': {'E(Ri)': 'Expected return on asset i', 'λ0': 'Risk-free rate or factor risk premium for λ0', 'λj': 'Risk premium for factor j', 'βij': 'Sensitivity of asset i to factor j'}}, 'relationship_to_multifactor_models': {'apt_foundation': 'APT provides theoretical foundation for multifactor models', 'practical_implementation': 'Multifactor models are practical implementations of APT', 'factor_identification': "APT doesn't specify factors; models must identify relevant factors"}, 'advantages': ['More general than CAPM', 'Allows for multiple risk factors', 'No specific utility function required', 'Fewer restrictive assumptions than CAPM'], 'limitations': ["Doesn't specify which factors to use", 'Factor risk premiums must be estimated', 'Requires large portfolios for diversification assumption', 'Testing APT is challenging empirically']}

    @staticmethod
    def identify_arbitrage_opportunity(expected_returns: np.ndarray, factor_loadings: np.ndarray, factor_risk_premiums: np.ndarray, risk_free_rate: float=0.03) -> Dict:
        """Identify arbitrage opportunities using APT"""
        apt_expected_returns = risk_free_rate + np.dot(factor_loadings, factor_risk_premiums)
        return_differences = expected_returns - apt_expected_returns
        arbitrage_opportunities = []
        for i, diff in enumerate(return_differences):
            if abs(diff) > 0.005:
                arbitrage_opportunities.append({'asset_index': i, 'expected_return': expected_returns[i], 'apt_fair_value': apt_expected_returns[i], 'difference': diff, 'direction': 'Overvalued' if diff < 0 else 'Undervalued', 'arbitrage_potential': abs(diff)})
        return {'arbitrage_opportunities': arbitrage_opportunities, 'number_of_opportunities': len(arbitrage_opportunities), 'largest_opportunity': max(arbitrage_opportunities, key=lambda x: x['arbitrage_potential']) if arbitrage_opportunities else None, 'market_efficiency_assessment': MultifactorModels._assess_market_efficiency(return_differences)}

    @staticmethod
    def calculate_expected_return_multifactor(factor_sensitivities: np.ndarray, factor_risk_premiums: np.ndarray, risk_free_rate: float=0.03) -> Dict:
        """Calculate expected return using multifactor model"""
        factor_contributions = factor_sensitivities * factor_risk_premiums
        total_risk_premium = np.sum(factor_contributions)
        expected_return = risk_free_rate + total_risk_premium
        return {'expected_return': expected_return, 'risk_free_rate': risk_free_rate, 'total_risk_premium': total_risk_premium, 'factor_contributions': {f'factor_{i + 1}': {'sensitivity': factor_sensitivities[i], 'risk_premium': factor_risk_premiums[i], 'contribution': factor_contributions[i]} for i in range(len(factor_sensitivities))}, 'decomposition_analysis': MultifactorModels._analyze_return_decomposition(factor_contributions, total_risk_premium)}

    @staticmethod
    def compare_factor_models() -> Dict:
        """Compare different types of factor models"""
        return {'macroeconomic_factor_models': {'description': 'Use observable economic variables as factors', 'examples': ['GDP growth', 'Inflation', 'Interest rates', 'Oil prices'], 'advantages': ['Intuitive economic interpretation', 'Factors are observable', 'Good for scenario analysis', 'Useful for risk management'], 'disadvantages': ['May miss important risk factors', 'Economic factors may be correlated', 'Factor loadings must be estimated', 'Limited number of factors'], 'typical_applications': ['Asset allocation', 'Risk management', 'Scenario analysis']}, 'fundamental_factor_models': {'description': 'Use company/security fundamental attributes as factors', 'examples': ['P/E ratio', 'Book-to-market', 'Market cap', 'Earnings growth'], 'advantages': ['Factors directly observable from financial data', 'Good for security selection', 'Many factors can be included', 'Useful for portfolio construction'], 'disadvantages': ['Factor returns must be estimated', 'May have multicollinearity issues', 'Requires frequent factor updating', 'Survivorship bias in factor construction'], 'typical_applications': ['Security selection', 'Portfolio construction', 'Performance attribution']}, 'statistical_factor_models': {'description': 'Use statistical techniques to extract factors from return data', 'examples': ['Principal component analysis', 'Factor analysis', 'Independent component analysis'], 'advantages': ['Factors explain maximum return variation', 'No need to specify factors a priori', 'Factors are orthogonal', 'Good statistical properties'], 'disadvantages': ['Factors lack economic interpretation', 'Factors may be unstable over time', 'Difficult to use for forecasting', 'Black box approach'], 'typical_applications': ['Risk modeling', 'Portfolio optimization', 'Performance measurement']}}

    @staticmethod
    def analyze_multifactor_model_uses(portfolio_data: Dict) -> Dict:
        """Analyze uses of multifactor models"""
        uses = {'risk_management': {'description': 'Decompose portfolio risk into factor exposures', 'applications': ['Track factor exposures relative to benchmark', 'Identify concentrated factor bets', 'Stress test portfolio under factor scenarios', 'Set factor exposure limits'], 'example_analysis': MultifactorModels._example_risk_decomposition(portfolio_data)}, 'portfolio_construction': {'description': 'Build portfolios with desired factor exposures', 'applications': ['Optimize portfolio for factor exposures', 'Create factor-neutral portfolios', 'Implement factor tilts', 'Control unintended factor bets'], 'optimization_considerations': ['Transaction costs and turnover', 'Factor exposure constraints', 'Risk budgeting across factors', 'Implementation efficiency']}, 'performance_attribution': {'description': 'Attribute portfolio performance to factor exposures', 'applications': ['Separate alpha from factor returns', 'Identify sources of outperformance', 'Evaluate manager skill vs factor timing', 'Benchmark factor-adjusted performance'], 'attribution_framework': MultifactorModels._performance_attribution_framework()}}
        return uses

    @staticmethod
    def multiple_risk_dimensions_benefits() -> Dict:
        """Describe benefits of considering multiple risk dimensions"""
        return {'comprehensive_risk_capture': {'single_factor_limitations': 'Single factor (like market beta) may miss important risks', 'multifactor_advantages': 'Captures various sources of systematic risk', 'risk_factor_examples': ['Market risk (beta)', 'Size risk (small vs large cap)', 'Value risk (value vs growth)', 'Momentum risk', 'Quality risk', 'Volatility risk']}, 'improved_risk_measurement': {'better_diversification_assessment': 'Identifies true diversification vs correlated factor exposures', 'concentrated_risk_identification': 'Reveals hidden concentrations in factor exposures', 'stress_testing_enhancement': 'Enables factor-based scenario analysis', 'tail_risk_modeling': 'Better modeling of extreme events through factor interactions'}, 'enhanced_portfolio_construction': {'factor_based_allocation': 'Allocate risk budget across multiple factors', 'smart_beta_implementation': 'Systematic factor exposure implementation', 'alpha_separation': 'Separate factor returns from true alpha generation', 'benchmark_relative_positioning': 'Control factor exposures relative to benchmark'}, 'practical_applications': {'asset_allocation': 'Factor-based strategic asset allocation', 'security_selection': 'Factor-aware security selection process', 'risk_budgeting': 'Allocate risk across factors rather than just assets', 'performance_evaluation': 'Factor-adjusted performance measurement'}}

    @staticmethod
    def _assess_market_efficiency(return_differences: np.ndarray) -> Dict:
        """Assess market efficiency based on APT deviations"""
        abs_differences = np.abs(return_differences)
        mean_abs_difference = np.mean(abs_differences)
        max_abs_difference = np.max(abs_differences)
        if mean_abs_difference < 0.01:
            efficiency = 'High'
            assessment = 'Market appears highly efficient'
        elif mean_abs_difference < 0.02:
            efficiency = 'Moderate'
            assessment = 'Some inefficiencies present'
        else:
            efficiency = 'Low'
            assessment = 'Significant inefficiencies detected'
        return {'efficiency_level': efficiency, 'assessment': assessment, 'mean_absolute_deviation': mean_abs_difference, 'maximum_deviation': max_abs_difference, 'number_of_large_deviations': np.sum(abs_differences > 0.02)}

@staticmethod
def identify_arbitrage_opportunity(expected_returns: np.ndarray, factor_loadings: np.ndarray, factor_risk_premiums: np.ndarray, risk_free_rate: float=0.03) -> Dict:
    """Identify arbitrage opportunities using APT"""
    apt_expected_returns = risk_free_rate + np.dot(factor_loadings, factor_risk_premiums)
    return_differences = expected_returns - apt_expected_returns
    arbitrage_opportunities = []
    for i, diff in enumerate(return_differences):
        if abs(diff) > 0.005:
            arbitrage_opportunities.append({'asset_index': i, 'expected_return': expected_returns[i], 'apt_fair_value': apt_expected_returns[i], 'difference': diff, 'direction': 'Overvalued' if diff < 0 else 'Undervalued', 'arbitrage_potential': abs(diff)})
    return {'arbitrage_opportunities': arbitrage_opportunities, 'number_of_opportunities': len(arbitrage_opportunities), 'largest_opportunity': max(arbitrage_opportunities, key=lambda x: x['arbitrage_potential']) if arbitrage_opportunities else None, 'market_efficiency_assessment': MultifactorModels._assess_market_efficiency(return_differences)}

class ActiveRiskTracking:
    """Active risk sources and tracking analysis"""

    @staticmethod
    def decompose_active_risk(portfolio_weights: np.ndarray, benchmark_weights: np.ndarray, factor_exposures: np.ndarray, factor_covariance: np.ndarray, specific_risk: np.ndarray) -> Dict:
        """Decompose active risk into factor and specific components"""
        active_weights = portfolio_weights - benchmark_weights
        portfolio_factor_exposure = np.dot(active_weights, factor_exposures)
        factor_risk = np.sqrt(np.dot(portfolio_factor_exposure, np.dot(factor_covariance, portfolio_factor_exposure)))
        specific_risk_contribution = np.sqrt(np.dot(active_weights ** 2, specific_risk ** 2))
        total_active_risk = np.sqrt(factor_risk ** 2 + specific_risk_contribution ** 2)
        return {'total_active_risk': total_active_risk, 'factor_risk_contribution': factor_risk, 'specific_risk_contribution': specific_risk_contribution, 'factor_risk_percentage': factor_risk / total_active_risk * 100 if total_active_risk > 0 else 0, 'specific_risk_percentage': specific_risk_contribution / total_active_risk * 100 if total_active_risk > 0 else 0, 'risk_decomposition_analysis': ActiveRiskTracking._analyze_risk_decomposition(factor_risk, specific_risk_contribution, total_active_risk)}

    @staticmethod
    def calculate_tracking_risk(portfolio_returns: np.ndarray, benchmark_returns: np.ndarray, rolling_window: int=252) -> Dict:
        """Calculate tracking risk with rolling analysis"""
        active_returns = portfolio_returns - benchmark_returns
        tracking_risk = np.std(active_returns, ddof=1) * MathConstants.SQRT_TRADING_DAYS
        rolling_tracking_risk = []
        for i in range(rolling_window, len(active_returns)):
            window_returns = active_returns[i - rolling_window:i]
            rolling_te = np.std(window_returns, ddof=1) * MathConstants.SQRT_TRADING_DAYS
            rolling_tracking_risk.append(rolling_te)
        rolling_tracking_risk = np.array(rolling_tracking_risk)
        return {'tracking_risk_annualized': tracking_risk, 'rolling_tracking_risk': rolling_tracking_risk, 'tracking_risk_statistics': {'mean_rolling_te': np.mean(rolling_tracking_risk), 'std_rolling_te': np.std(rolling_tracking_risk), 'min_rolling_te': np.min(rolling_tracking_risk), 'max_rolling_te': np.max(rolling_tracking_risk)}, 'tracking_risk_stability': ActiveRiskTracking._assess_tracking_risk_stability(rolling_tracking_risk), 'active_return_analysis': ActiveRiskTracking._analyze_active_returns(active_returns)}

    @staticmethod
    def sources_of_active_risk() -> Dict:
        """Identify and explain sources of active risk"""
        return {'asset_allocation_risk': {'description': 'Risk from deviating from benchmark asset allocation', 'sources': ['Sector allocation differences', 'Geographic allocation differences', 'Style allocation differences', 'Market cap allocation differences'], 'measurement': 'Track active weights in each allocation dimension', 'management': 'Set allocation limits and monitor regularly'}, 'security_selection_risk': {'description': 'Risk from selecting different securities within allocations', 'sources': ['Stock picking within sectors', 'Bond selection within duration/credit buckets', 'Overweight/underweight individual positions', 'Security-specific events'], 'measurement': 'Analyze stock-specific active weights and performance', 'management': 'Diversification limits and position sizing rules'}, 'factor_exposure_risk': {'description': 'Risk from different factor exposures vs benchmark', 'sources': ['Value vs growth tilt', 'Size factor exposure', 'Quality factor exposure', 'Momentum factor exposure', 'Volatility factor exposure'], 'measurement': 'Factor exposure analysis vs benchmark', 'management': 'Factor exposure limits and hedging'}, 'timing_risk': {'description': 'Risk from timing allocation and selection decisions', 'sources': ['Market timing attempts', 'Sector rotation timing', 'Entry/exit timing for positions', 'Rebalancing timing'], 'measurement': 'Performance attribution across time periods', 'management': 'Systematic processes and reduced discretionary timing'}}

    @staticmethod
    def _analyze_risk_decomposition(factor_risk: float, specific_risk: float, total_risk: float) -> Dict:
        """Analyze the risk decomposition results"""
        factor_dominance = factor_risk > specific_risk
        analysis = {'dominant_risk_source': 'Factor Risk' if factor_dominance else 'Specific Risk', 'risk_concentration': 'High' if max(factor_risk, specific_risk) / total_risk > 0.8 else 'Moderate', 'diversification_effectiveness': 'Good' if min(factor_risk, specific_risk) / total_risk > 0.2 else 'Poor'}
        if factor_dominance:
            analysis['implications'] = ['Portfolio risk driven by systematic factor exposures', 'Consider factor hedging to reduce risk', 'Factor timing may be significant component of returns']
        else:
            analysis['implications'] = ['Portfolio risk driven by security-specific factors', 'Diversification may help reduce risk', 'Stock selection appears to be primary focus']
        return analysis

    @staticmethod
    def _assess_tracking_risk_stability(rolling_tracking_risk: np.ndarray) -> Dict:
        """Assess stability of tracking risk over time"""
        coefficient_of_variation = np.std(rolling_tracking_risk) / np.mean(rolling_tracking_risk)
        if coefficient_of_variation < 0.2:
            stability = 'High'
            assessment = 'Tracking risk is very stable'
        elif coefficient_of_variation < 0.4:
            stability = 'Moderate'
            assessment = 'Tracking risk shows some variation'
        else:
            stability = 'Low'
            assessment = 'Tracking risk is highly variable'
        return {'stability_level': stability, 'assessment': assessment, 'coefficient_of_variation': coefficient_of_variation, 'trend_analysis': 'Increasing' if rolling_tracking_risk[-1] > rolling_tracking_risk[0] else 'Decreasing'}

    @staticmethod
    def _analyze_active_returns(active_returns: np.ndarray) -> Dict:
        """Analyze active return characteristics"""
        return {'mean_active_return': np.mean(active_returns) * MathConstants.TRADING_DAYS_YEAR, 'active_return_volatility': np.std(active_returns, ddof=1) * MathConstants.SQRT_TRADING_DAYS, 'active_return_skewness': ActiveRiskTracking._calculate_skewness(active_returns), 'hit_rate': np.sum(active_returns > 0) / len(active_returns), 'up_capture': np.mean(active_returns[active_returns > 0]) if np.any(active_returns > 0) else 0, 'down_capture': np.mean(active_returns[active_returns < 0]) if np.any(active_returns < 0) else 0}

    @staticmethod
    def _calculate_skewness(data: np.ndarray) -> float:
        """Calculate skewness of data"""
        mean = np.mean(data)
        std = np.std(data, ddof=1)
        n = len(data)
        if std == 0:
            return 0
        skewness = n / ((n - 1) * (n - 2)) * np.sum(((data - mean) / std) ** 3)
        return skewness

@staticmethod
def _analyze_risk_decomposition(factor_risk: float, specific_risk: float, total_risk: float) -> Dict:
    """Analyze the risk decomposition results"""
    factor_dominance = factor_risk > specific_risk
    analysis = {'dominant_risk_source': 'Factor Risk' if factor_dominance else 'Specific Risk', 'risk_concentration': 'High' if max(factor_risk, specific_risk) / total_risk > 0.8 else 'Moderate', 'diversification_effectiveness': 'Good' if min(factor_risk, specific_risk) / total_risk > 0.2 else 'Poor'}
    if factor_dominance:
        analysis['implications'] = ['Portfolio risk driven by systematic factor exposures', 'Consider factor hedging to reduce risk', 'Factor timing may be significant component of returns']
    else:
        analysis['implications'] = ['Portfolio risk driven by security-specific factors', 'Diversification may help reduce risk', 'Stock selection appears to be primary focus']
    return analysis

class ActiveManagement:
    """Main active portfolio management interface"""

    def __init__(self):
        self.value_measurement = ValueAddedMeasurement()
        self.ir_analysis = InformationRatioAnalysis()
        self.fundamental_law = FundamentalLawActiveManagement()
        self.multifactor_models = MultifactorModels()
        self.active_risk_tracking = ActiveRiskTracking()
        self.strategy_combination = StrategyCombination()

    def comprehensive_active_management_analysis(self, portfolio_data: Dict, benchmark_data: Dict, factor_data: Optional[Dict]=None) -> Dict:
        """Comprehensive active management analysis"""
        portfolio_returns = np.array(portfolio_data.get('returns', []))
        benchmark_returns = np.array(benchmark_data.get('returns', []))
        value_added = self.value_measurement.calculate_value_added(portfolio_returns, benchmark_returns)
        ir_analysis = self.ir_analysis.calculate_information_ratio_ex_post(portfolio_returns, benchmark_returns)
        if 'fundamental_law_inputs' in portfolio_data:
            fl_analysis = self.fundamental_law.calculate_fundamental_law_components(portfolio_data['fundamental_law_inputs'])
        else:
            fl_analysis = {'note': 'Fundamental law inputs not provided'}
        risk_analysis = {}
        if factor_data:
            portfolio_weights = np.array(portfolio_data.get('weights', []))
            benchmark_weights = np.array(benchmark_data.get('weights', []))
            if len(portfolio_weights) == len(benchmark_weights):
                risk_analysis = self.active_risk_tracking.decompose_active_risk(portfolio_weights, benchmark_weights, factor_data.get('factor_exposures', np.array([])), factor_data.get('factor_covariance', np.array([])), factor_data.get('specific_risk', np.array([])))
        tracking_analysis = self.active_risk_tracking.calculate_tracking_risk(portfolio_returns, benchmark_returns)
        return {'value_added_analysis': value_added, 'information_ratio_analysis': ir_analysis, 'fundamental_law_analysis': fl_analysis, 'risk_decomposition': risk_analysis, 'tracking_risk_analysis': tracking_analysis, 'active_management_assessment': self._assess_active_management_quality(value_added, ir_analysis, tracking_analysis), 'improvement_recommendations': self._generate_improvement_recommendations(value_added, ir_analysis, fl_analysis)}

    def manager_selection_analysis(self, manager_candidates: List[Dict]) -> Dict:
        """Analyze and compare active manager candidates"""
        manager_scores = {}
        for i, manager in enumerate(manager_candidates):
            manager_id = manager.get('manager_id', f'Manager_{i + 1}')
            returns = np.array(manager.get('returns', []))
            benchmark_returns = np.array(manager.get('benchmark_returns', []))
            if len(returns) > 0 and len(benchmark_returns) > 0:
                ir_analysis = self.ir_analysis.calculate_information_ratio_ex_post(returns, benchmark_returns)
                score = self._calculate_manager_score(ir_analysis, manager)
                manager_scores[manager_id] = {'information_ratio': ir_analysis['information_ratio_annualized'], 'tracking_error': ir_analysis['tracking_error_annualized'], 'active_return': ir_analysis['active_return_annualized'], 'overall_score': score, 'strengths': self._identify_manager_strengths(ir_analysis, manager), 'concerns': self._identify_manager_concerns(ir_analysis, manager)}
        ranked_managers = sorted(manager_scores.items(), key=lambda x: x[1]['overall_score'], reverse=True)
        return {'manager_analysis': manager_scores, 'manager_ranking': [manager[0] for manager in ranked_managers], 'top_manager': ranked_managers[0][0] if ranked_managers else None, 'selection_criteria': self._define_manager_selection_criteria(), 'due_diligence_framework': self._manager_due_diligence_framework()}

    def factor_model_implementation(self, factor_data: Dict) -> Dict:
        """Implement and analyze factor model for active management"""
        apt_analysis = self.multifactor_models.arbitrage_pricing_theory_analysis()
        model_comparison = self.multifactor_models.compare_factor_models()
        risk_benefits = self.multifactor_models.multiple_risk_dimensions_benefits()
        model_uses = self.multifactor_models.analyze_multifactor_model_uses(factor_data)
        return {'apt_framework': apt_analysis, 'factor_model_comparison': model_comparison, 'multiple_risk_dimensions': risk_benefits, 'practical_applications': model_uses, 'implementation_recommendations': self._factor_model_implementation_recommendations(factor_data)}

    def _assess_active_management_quality(self, value_added: Dict, ir_analysis: Dict, tracking_analysis: Dict) -> Dict:
        """Assess overall active management quality"""
        ir = ir_analysis.get('information_ratio_annualized', 0)
        active_return = value_added.get('active_return_annualized', 0)
        hit_rate = value_added.get('hit_rate', 0.5)
        quality_score = 0
        if ir > 0.5:
            quality_score += 40
        elif ir > 0.25:
            quality_score += 30
        elif ir > 0:
            quality_score += 20
        if active_return > 0.02:
            quality_score += 30
        elif active_return > 0:
            quality_score += 20
        if hit_rate > 0.6:
            quality_score += 20
        elif hit_rate > 0.5:
            quality_score += 15
        te_stability = tracking_analysis.get('tracking_risk_stability', {}).get('stability_level', 'Low')
        if te_stability == 'High':
            quality_score += 10
        elif te_stability == 'Moderate':
            quality_score += 5
        return {'quality_score': quality_score, 'quality_rating': 'Excellent' if quality_score > 80 else 'Good' if quality_score > 60 else 'Average' if quality_score > 40 else 'Poor', 'key_strengths': self._identify_key_strengths(ir, active_return, hit_rate), 'areas_for_improvement': self._identify_improvement_areas(ir, active_return, hit_rate)}

    def _generate_improvement_recommendations(self, value_added: Dict, ir_analysis: Dict, fl_analysis: Dict) -> List[str]:
        """Generate specific improvement recommendations"""
        recommendations = []
        ir = ir_analysis.get('information_ratio_annualized', 0)
        if ir < 0.25:
            recommendations.append('Focus on improving information ratio through better forecasting or risk control')
        hit_rate = value_added.get('hit_rate', 0.5)
        if hit_rate < 0.55:
            recommendations.append('Improve hit rate through better market timing or security selection')
        if 'fundamental_law_inputs' in fl_analysis:
            fl_inputs = fl_analysis.get('fundamental_law_inputs', {})
            ic = fl_inputs.get('information_coefficient', 0)
            breadth = fl_inputs.get('breadth', 0)
            tc = fl_inputs.get('transfer_coefficient', 0)
            if ic < 0.05:
                recommendations.append('Enhance forecasting skill (information coefficient)')
            if breadth < 50:
                recommendations.append('Increase breadth of investment opportunities')
            if tc < 0.7:
                recommendations.append('Improve implementation efficiency (transfer coefficient)')
        if not recommendations:
            recommendations.append('Continue current strategy while monitoring for performance persistence')
        return recommendations

    def _calculate_manager_score(self, ir_analysis: Dict, manager_data: Dict) -> float:
        """Calculate overall manager score"""
        ir = ir_analysis.get('information_ratio_annualized', 0)
        track_record_length = manager_data.get('track_record_years', 3)
        assets_under_management = manager_data.get('aum_billions', 1)
        base_score = min(100, max(0, ir * 100)) * 0.6
        track_record_score = min(25, track_record_length * 5)
        if 1 <= assets_under_management <= 10:
            aum_score = 15
        elif 0.5 <= assets_under_management <= 20:
            aum_score = 10
        else:
            aum_score = 5
        return base_score + track_record_score + aum_score

    def _identify_manager_strengths(self, ir_analysis: Dict, manager_data: Dict) -> List[str]:
        """Identify manager strengths"""
        strengths = []
        ir = ir_analysis.get('information_ratio_annualized', 0)
        if ir > 0.5:
            strengths.append('Excellent risk-adjusted performance')
        active_return = ir_analysis.get('active_return_annualized', 0)
        if active_return > 0.02:
            strengths.append('Strong active return generation')
        track_record = manager_data.get('track_record_years', 3)
        if track_record > 5:
            strengths.append('Long track record demonstrates consistency')
        return strengths

    def _factor_model_implementation_recommendations(self, factor_data: Dict) -> List[str]:
        """Provide factor model implementation recommendations"""
        recommendations = ['Start with fundamental factor model for intuitive factor interpretation', 'Ensure factor data quality and regular updates', 'Implement robust factor exposure monitoring', 'Use factor models for risk budgeting and portfolio construction', 'Regular model validation and performance testing', 'Consider transaction costs in factor-based strategies']
        return recommendations

    def _identify_key_strengths(self, ir: float, active_return: float, hit_rate: float) -> List[str]:
        """Identify key strengths of active management"""
        strengths = []
        if ir > 0.5:
            strengths.append('Excellent information ratio')
        if active_return > 0.015:
            strengths.append('Strong active return generation')
        if hit_rate > 0.6:
            strengths.append('High hit rate indicates good timing')
        return strengths

    def _identify_improvement_areas(self, ir: float, active_return: float, hit_rate: float) -> List[str]:
        """Identify areas for improvement"""
        areas = []
        if ir < 0.25:
            areas.append('Information ratio below industry average')
        if active_return < 0.005:
            areas.append('Limited active return generation')
        if hit_rate < 0.5:
            areas.append('Hit rate below 50% indicates poor timing')
        return areas

