class CAPMAnalysis:
    """Capital Asset Pricing Model implementation"""

    @staticmethod
    def expected_return(beta: float, risk_free_rate: float=MathConstants.DEFAULT_RISK_FREE_RATE, market_return: float=0.1) -> float:
        """Calculate expected return using CAPM"""
        return risk_free_rate + beta * (market_return - risk_free_rate)

    @staticmethod
    def security_market_line(betas: np.ndarray, risk_free_rate: float=MathConstants.DEFAULT_RISK_FREE_RATE, market_return: float=0.1) -> np.ndarray:
        """Generate Security Market Line for given betas"""
        return risk_free_rate + betas * (market_return - risk_free_rate)

    @staticmethod
    def alpha_calculation(actual_returns: np.ndarray, market_returns: np.ndarray, risk_free_rate: float=MathConstants.DEFAULT_RISK_FREE_RATE) -> Dict:
        """Calculate Jensen's alpha and related metrics"""
        beta = StatisticalCalculations.calculate_beta(actual_returns, market_returns)
        avg_actual_return = np.mean(actual_returns) * MathConstants.TRADING_DAYS_YEAR
        avg_market_return = np.mean(market_returns) * MathConstants.TRADING_DAYS_YEAR
        expected_return = CAPMAnalysis.expected_return(beta, risk_free_rate, avg_market_return)
        alpha = avg_actual_return - expected_return
        return {'alpha': alpha, 'beta': beta, 'actual_return': avg_actual_return, 'expected_return': expected_return, 'market_return': avg_market_return, 'excess_return': avg_actual_return - risk_free_rate, 'market_premium': avg_market_return - risk_free_rate}

    @staticmethod
    def capm_assumptions_check(returns_data: Dict[str, np.ndarray]) -> Dict:
        """Check CAPM assumptions validity"""
        assumptions = {'homogeneous_expectations': 'Cannot verify with historical data', 'single_period_model': 'Using historical multi-period data', 'risk_free_borrowing_lending': 'Assumed available', 'no_transaction_costs': 'Assumed', 'normal_distribution': {}, 'constant_correlations': {}}
        from scipy import stats
        for asset, returns in returns_data.items():
            shapiro_stat, shapiro_p = stats.shapiro(returns[:min(5000, len(returns))])
            assumptions['normal_distribution'][asset] = {'shapiro_test_p_value': shapiro_p, 'approximately_normal': shapiro_p > 0.05}
        if len(returns_data) >= 2:
            assets = list(returns_data.keys())
            asset1_returns = returns_data[assets[0]]
            asset2_returns = returns_data[assets[1]]
            mid_point = len(asset1_returns) // 2
            corr1 = StatisticalCalculations.calculate_correlation(asset1_returns[:mid_point], asset2_returns[:mid_point])
            corr2 = StatisticalCalculations.calculate_correlation(asset1_returns[mid_point:], asset2_returns[mid_point:])
            assumptions['constant_correlations'] = {'first_half_correlation': corr1, 'second_half_correlation': corr2, 'correlation_difference': abs(corr1 - corr2), 'stable_correlations': abs(corr1 - corr2) < 0.2}
        return assumptions

@staticmethod
def capm_assumptions_check(returns_data: Dict[str, np.ndarray]) -> Dict:
    """Check CAPM assumptions validity"""
    assumptions = {'homogeneous_expectations': 'Cannot verify with historical data', 'single_period_model': 'Using historical multi-period data', 'risk_free_borrowing_lending': 'Assumed available', 'no_transaction_costs': 'Assumed', 'normal_distribution': {}, 'constant_correlations': {}}
    from scipy import stats
    for asset, returns in returns_data.items():
        shapiro_stat, shapiro_p = stats.shapiro(returns[:min(5000, len(returns))])
        assumptions['normal_distribution'][asset] = {'shapiro_test_p_value': shapiro_p, 'approximately_normal': shapiro_p > 0.05}
    if len(returns_data) >= 2:
        assets = list(returns_data.keys())
        asset1_returns = returns_data[assets[0]]
        asset2_returns = returns_data[assets[1]]
