@staticmethod
def create_commodity_index(commodity_data: List[Dict[str, Any]], name: str='Custom Commodity Index') -> Dict[str, Any]:
    """Create commodity index"""
    total_weight = sum((commodity['weight'] for commodity in commodity_data))
    for commodity in commodity_data:
        commodity['normalized_weight'] = commodity['weight'] / total_weight
    index_value = sum((commodity['normalized_weight'] * commodity['price_index'] for commodity in commodity_data))
