class DateUtils:
    """Date utility functions for financial calculations"""

    @staticmethod
    def year_fraction(start_date: Union[datetime, date], end_date: Union[datetime, date], day_count: DayCountConvention=DayCountConvention.ACT_365) -> float:
        """Calculate year fraction between dates"""
        if isinstance(start_date, date):
            start_date = datetime.combine(start_date, datetime.min.time())
        if isinstance(end_date, date):
            end_date = datetime.combine(end_date, datetime.min.time())
        if end_date <= start_date:
            return 0.0
        if day_count == DayCountConvention.ACT_365:
            return (end_date - start_date).days / 365.0
        elif day_count == DayCountConvention.ACT_360:
            return (end_date - start_date).days / 360.0
        elif day_count == DayCountConvention.THIRTY_360:
            return DateUtils._thirty_360_fraction(start_date, end_date)
        elif day_count == DayCountConvention.ACT_ACT:
            return DateUtils._act_act_fraction(start_date, end_date)
        else:
            return (end_date - start_date).days / 365.0

    @staticmethod
    def _thirty_360_fraction(start_date: datetime, end_date: datetime) -> float:
        """30/360 day count calculation"""
        start_day = min(start_date.day, 30)
        end_day = end_date.day
        if start_day == 30 and end_day == 31:
            end_day = 30
        days = 360 * (end_date.year - start_date.year) + 30 * (end_date.month - start_date.month) + (end_day - start_day)
        return days / 360.0

    @staticmethod
    def _act_act_fraction(start_date: datetime, end_date: datetime) -> float:
        """ACT/ACT day count calculation"""
        total_days = 0
        current_year = start_date.year
        current_date = start_date
        while current_date < end_date:
            year_end = datetime(current_year, 12, 31)
            next_year_start = datetime(current_year + 1, 1, 1)
            if end_date <= year_end:
                days_in_year = (end_date - current_date).days
                year_length = 366 if calendar.isleap(current_year) else 365
                total_days += days_in_year / year_length
                break
            else:
                days_in_year = (next_year_start - current_date).days
                year_length = 366 if calendar.isleap(current_year) else 365
                total_days += days_in_year / year_length
                current_year += 1
                current_date = next_year_start
        return total_days

    @staticmethod
    def add_tenor(start_date: Union[datetime, date], tenor: str) -> datetime:
        """Add tenor to date (e.g., '3M', '1Y', '6W')"""
        if isinstance(start_date, date):
            start_date = datetime.combine(start_date, datetime.min.time())
        tenor = tenor.upper()
        if tenor.endswith('D'):
            days = int(tenor[:-1])
            return start_date + timedelta(days=days)
        elif tenor.endswith('W'):
            weeks = int(tenor[:-1])
            return start_date + timedelta(weeks=weeks)
        elif tenor.endswith('M'):
            months = int(tenor[:-1])
            new_month = start_date.month + months
            new_year = start_date.year + (new_month - 1) // 12
            new_month = (new_month - 1) % 12 + 1
            try:
                return start_date.replace(year=new_year, month=new_month)
            except ValueError:
                last_day = calendar.monthrange(new_year, new_month)[1]
                return start_date.replace(year=new_year, month=new_month, day=last_day)
        elif tenor.endswith('Y'):
            years = int(tenor[:-1])
            try:
                return start_date.replace(year=start_date.year + years)
            except ValueError:
                return start_date.replace(year=start_date.year + years, month=2, day=28)
        else:
            raise ValueError(f'Invalid tenor format: {tenor}')

    @staticmethod
    def generate_schedule(start_date: Union[datetime, date], end_date: Union[datetime, date], frequency: str='3M', business_day_convention: str='modified_following') -> List[datetime]:
        """Generate payment schedule between dates"""
        if isinstance(start_date, date):
            start_date = datetime.combine(start_date, datetime.min.time())
        if isinstance(end_date, date):
            end_date = datetime.combine(end_date, datetime.min.time())
        schedule = []
        current_date = start_date
        bdc = BusinessDayCalculator()
        while current_date < end_date:
            next_date = DateUtils.add_tenor(current_date, frequency)
            if next_date > end_date:
                next_date = end_date
            if business_day_convention == 'following':
                while not bdc.is_business_day(next_date):
                    next_date += timedelta(days=1)
            elif business_day_convention == 'preceding':
                while not bdc.is_business_day(next_date):
                    next_date -= timedelta(days=1)
            elif business_day_convention == 'modified_following':
                original_month = next_date.month
                while not bdc.is_business_day(next_date):
                    next_date += timedelta(days=1)
                    if next_date.month != original_month:
                        next_date = DateUtils.add_tenor(current_date, frequency)
                        while not bdc.is_business_day(next_date):
                            next_date -= timedelta(days=1)
                        break
            schedule.append(next_date)
            current_date = next_date
        return schedule

@staticmethod
def _thirty_360_fraction(start_date: datetime, end_date: datetime) -> float:
    """30/360 day count calculation"""
    start_day = min(start_date.day, 30)
    end_day = end_date.day
    if start_day == 30 and end_day == 31:
        end_day = 30
    days = 360 * (end_date.year - start_date.year) + 30 * (end_date.month - start_date.month) + (end_day - start_day)
    return days / 360.0

@dataclass
class CurveData:
    """Interest rate curve data"""
    curve_date: datetime
    curve_type: str
    currency: str
    day_count: DayCountConvention
    points: List[YieldCurvePoint] = field(default_factory=list)

    def add_point(self, maturity: float, rate: float, instrument_type: str='government'):
        """Add point to curve"""
        self.points.append(YieldCurvePoint(maturity, rate, instrument_type))
        self.points.sort(key=lambda x: x.maturity)

    def interpolate_rate(self, maturity: float, method: str='linear') -> float:
        """Interpolate rate for given maturity"""
        if not self.points:
            raise ValueError('No curve points available')
        sorted_points = sorted(self.points, key=lambda x: x.maturity)
        if maturity <= sorted_points[0].maturity:
            return sorted_points[0].rate
        if maturity >= sorted_points[-1].maturity:
            return sorted_points[-1].rate
        for i in range(len(sorted_points) - 1):
            if sorted_points[i].maturity <= maturity <= sorted_points[i + 1].maturity:
                if method == 'linear':
                    return self._linear_interpolation(sorted_points[i], sorted_points[i + 1], maturity)
                elif method == 'cubic':
                    return self._cubic_interpolation(sorted_points, maturity, i)
        raise ValueError(f'Cannot interpolate rate for maturity {maturity}')

    def _linear_interpolation(self, p1: YieldCurvePoint, p2: YieldCurvePoint, maturity: float) -> float:
        """Linear interpolation between two points"""
        if p2.maturity == p1.maturity:
            return p1.rate
        weight = (maturity - p1.maturity) / (p2.maturity - p1.maturity)
        return p1.rate + weight * (p2.rate - p1.rate)

    def _cubic_interpolation(self, points: List[YieldCurvePoint], maturity: float, index: int) -> float:
        """Cubic spline interpolation (simplified)"""
        return self._linear_interpolation(points[index], points[index + 1], maturity)

def interpolate_rate(self, maturity: float, method: str='linear') -> float:
    """Interpolate rate for given maturity"""
    if not self.points:
        raise ValueError('No curve points available')
    sorted_points = sorted(self.points, key=lambda x: x.maturity)
    if maturity <= sorted_points[0].maturity:
        return sorted_points[0].rate
    if maturity >= sorted_points[-1].maturity:
        return sorted_points[-1].rate
    for i in range(len(sorted_points) - 1):
        if sorted_points[i].maturity <= maturity <= sorted_points[i + 1].maturity:
            if method == 'linear':
                return self._linear_interpolation(sorted_points[i], sorted_points[i + 1], maturity)
            elif method == 'cubic':
                return self._cubic_interpolation(sorted_points, maturity, i)
    raise ValueError(f'Cannot interpolate rate for maturity {maturity}')

def _cubic_interpolation(self, points: List[YieldCurvePoint], maturity: float, index: int) -> float:
    """Cubic spline interpolation (simplified)"""
    return self._linear_interpolation(points[index], points[index + 1], maturity)

class DataCache:
    """Simple caching mechanism for market data"""

    def __init__(self, max_age_seconds: int=300):
        self.cache = {}
        self.max_age = max_age_seconds

    def get(self, key: str) -> Optional[Any]:
        """Get cached data if not expired"""
        if key in self.cache:
            data, timestamp = self.cache[key]
            age = (datetime.now() - timestamp).total_seconds()
            if age <= self.max_age:
                return data
            else:
                del self.cache[key]
        return None

    def set(self, key: str, data: Any):
        """Cache data with timestamp"""
        self.cache[key] = (data, datetime.now())

    def clear(self):
        """Clear all cached data"""
        self.cache.clear()

def get(self, key: str) -> Optional[Any]:
    """Get cached data if not expired"""
    if key in self.cache:
        data, timestamp = self.cache[key]
        age = (datetime.now() - timestamp).total_seconds()
        if age <= self.max_age:
            return data
        else:
            del self.cache[key]
    return None

class DerivativeInstrument(ABC):
    """
    Abstract base class for all derivative instruments.
    Implements common interface following CFA curriculum structure.
    """

    def __init__(self, derivative_type: DerivativeType, underlying_type: UnderlyingType, expiry_date: Union[datetime, date], notional: float=1.0, day_count: DayCountConvention=DayCountConvention.ACT_365):
        self.derivative_type = derivative_type
        self.underlying_type = underlying_type
        self.expiry_date = expiry_date
        self.notional = notional
        self.day_count = day_count
        self.creation_date = datetime.now()
        self._validate_inputs()

    def _validate_inputs(self):
        """Validate instrument parameters"""
        if self.notional <= 0:
            raise ValidationError('Notional amount must be positive')
        if isinstance(self.expiry_date, date):
            self.expiry_date = datetime.combine(self.expiry_date, datetime.min.time())
        if self.expiry_date <= self.creation_date:
            raise ValidationError('Expiry date must be in the future')

    @abstractmethod
    def calculate_payoff(self, spot_price: float) -> float:
        """Calculate payoff at expiration given spot price"""
        pass

    @abstractmethod
    def fair_value(self, market_data: MarketData) -> PricingResult:
        """Calculate fair value using appropriate pricing model"""
        pass

    def time_to_expiry(self, valuation_date: Optional[datetime]=None) -> float:
        """Calculate time to expiry in years"""
        if valuation_date is None:
            valuation_date = datetime.now()
        time_diff = self.expiry_date - valuation_date
        if self.day_count == DayCountConvention.ACT_365:
            return time_diff.total_seconds() / (365.25 * 24 * 3600)
        elif self.day_count == DayCountConvention.ACT_360:
            return time_diff.total_seconds() / (360 * 24 * 3600)
        elif self.day_count == DayCountConvention.THIRTY_360:
            return time_diff.days / 360
        else:
            return time_diff.total_seconds() / (365.25 * 24 * 3600)

    def is_expired(self, valuation_date: Optional[datetime]=None) -> bool:
        """Check if derivative has expired"""
        if valuation_date is None:
            valuation_date = datetime.now()
        return valuation_date >= self.expiry_date

    def __repr__(self) -> str:
        return f'{self.__class__.__name__}(type={self.derivative_type.value}, expiry={self.expiry_date})'

def time_to_expiry(self, valuation_date: Optional[datetime]=None) -> float:
    """Calculate time to expiry in years"""
    if valuation_date is None:
        valuation_date = datetime.now()
    time_diff = self.expiry_date - valuation_date
    if self.day_count == DayCountConvention.ACT_365:
        return time_diff.total_seconds() / (365.25 * 24 * 3600)
    elif self.day_count == DayCountConvention.ACT_360:
        return time_diff.total_seconds() / (360 * 24 * 3600)
    elif self.day_count == DayCountConvention.THIRTY_360:
        return time_diff.days / 360
    else:
        return time_diff.total_seconds() / (365.25 * 24 * 3600)

class ContingentClaim(DerivativeInstrument):
    """Base class for contingent claims (options)"""

    def __init__(self, option_type: OptionType, underlying_type: UnderlyingType, expiry_date: Union[datetime, date], strike_price: float, exercise_style: ExerciseStyle=ExerciseStyle.EUROPEAN, notional: float=1.0, day_count: DayCountConvention=DayCountConvention.ACT_365):
        super().__init__(DerivativeType.OPTION, underlying_type, expiry_date, notional, day_count)
        self.option_type = option_type
        self.strike_price = strike_price
        self.exercise_style = exercise_style
        if strike_price <= 0:
            raise ValidationError('Strike price must be positive')

    def moneyness(self, spot_price: float) -> str:
        """Determine option moneyness"""
        if self.option_type == OptionType.CALL:
            if spot_price > self.strike_price:
                return 'ITM'
            elif spot_price == self.strike_price:
                return 'ATM'
            else:
                return 'OTM'
        elif spot_price < self.strike_price:
            return 'ITM'
        elif spot_price == self.strike_price:
            return 'ATM'
        else:
            return 'OTM'

    def intrinsic_value(self, spot_price: float) -> float:
        """Calculate intrinsic value of option"""
        if self.option_type == OptionType.CALL:
            return max(0, spot_price - self.strike_price)
        else:
            return max(0, self.strike_price - spot_price)

def intrinsic_value(self, spot_price: float) -> float:
    """Calculate intrinsic value of option"""
    if self.option_type == OptionType.CALL:
        return max(0, spot_price - self.strike_price)
    else:
        return max(0, self.strike_price - spot_price)

def calculate_time_fraction(start_date: datetime, end_date: datetime, day_count: DayCountConvention=DayCountConvention.ACT_365) -> float:
    """
    Calculate time fraction between dates using specified day count convention

    Args:
        start_date: Start date
        end_date: End date
        day_count: Day count convention

    Returns:
        Time fraction in years
    """
    if end_date <= start_date:
        return 0.0
    time_diff = end_date - start_date
    if day_count == DayCountConvention.ACT_365:
        return time_diff.total_seconds() / (365.25 * 24 * 3600)
    elif day_count == DayCountConvention.ACT_360:
        return time_diff.total_seconds() / (360 * 24 * 3600)
    elif day_count == DayCountConvention.THIRTY_360:
        return time_diff.days / 360
    else:
        return time_diff.total_seconds() / (365.25 * 24 * 3600)

class DerivativesPortfolio:
    """Derivatives portfolio management and analytics"""

    def __init__(self, portfolio_id: str=None):
        self.portfolio_id = portfolio_id or f'portfolio_{datetime.now().strftime('%Y%m%d_%H%M%S')}'
        self.positions: List[PortfolioPosition] = []
        self.creation_date = datetime.now()
        self.last_update = None
        self.options_engine = BlackScholesPricingEngine()
        self.forwards_engine = ForwardCommitmentPricingEngine()

    def add_position(self, instrument: DerivativeInstrument, quantity: float, entry_price: float, entry_date: datetime=None):
        """Add position to portfolio"""
        if entry_date is None:
            entry_date = datetime.now()
        position = PortfolioPosition(instrument=instrument, quantity=quantity, entry_price=entry_price, entry_date=entry_date)
        self.positions.append(position)
        self.last_update = datetime.now()
        logger.info(f'Added position: {quantity} units of {instrument}')

    def remove_position(self, position_index: int):
        """Remove position from portfolio"""
        if 0 <= position_index < len(self.positions):
            removed_position = self.positions.pop(position_index)
            self.last_update = datetime.now()
            logger.info(f'Removed position: {removed_position.instrument}')
        else:
            raise ValueError('Invalid position index')

    def update_positions(self, market_data: MarketData) -> float:
        """Update all position values and calculate portfolio value"""
        total_value = 0.0
        for position in self.positions:
            try:
                if hasattr(position.instrument, 'option_type'):
                    pricing_result = self.options_engine.price(position.instrument, market_data)
                else:
                    pricing_result = self.forwards_engine.price(position.instrument, market_data)
                position.current_value = pricing_result.fair_value * position.quantity
                position.unrealized_pnl = position.current_value - position.entry_price * position.quantity
                total_value += position.current_value
            except Exception as e:
                logger.error(f'Error pricing position {position.instrument}: {e}')
                position.current_value = position.entry_price * position.quantity
                total_value += position.current_value
        self.last_update = datetime.now()
        return total_value

    def get_portfolio_greeks(self, market_data: MarketData) -> Dict[str, float]:
        """Calculate aggregated portfolio Greeks"""
        total_greeks = {'delta': 0.0, 'gamma': 0.0, 'theta': 0.0, 'vega': 0.0, 'rho': 0.0}
        for position in self.positions:
            if hasattr(position.instrument, 'option_type'):
                try:
                    greeks = self.options_engine.calculate_greeks(position.instrument, market_data)
                    total_greeks['delta'] += greeks.delta * position.quantity
                    total_greeks['gamma'] += greeks.gamma * position.quantity
                    total_greeks['theta'] += greeks.theta * position.quantity
                    total_greeks['vega'] += greeks.vega * position.quantity
                    total_greeks['rho'] += greeks.rho * position.quantity
                except Exception as e:
                    logger.warning(f'Could not calculate Greeks for {position.instrument}: {e}')
        return total_greeks

    def get_portfolio_summary(self, market_data: MarketData) -> Dict[str, Any]:
        """Get comprehensive portfolio summary"""
        portfolio_value = self.update_positions(market_data)
        greeks = self.get_portfolio_greeks(market_data)
        total_pnl = sum((pos.unrealized_pnl for pos in self.positions))
        return {'portfolio_id': self.portfolio_id, 'portfolio_value': portfolio_value, 'total_unrealized_pnl': total_pnl, 'number_of_positions': len(self.positions), 'last_update': self.last_update, 'greeks': greeks, 'positions_summary': [{'instrument_type': pos.instrument.derivative_type.value, 'quantity': pos.quantity, 'current_value': pos.current_value, 'unrealized_pnl': pos.unrealized_pnl, 'entry_date': pos.entry_date} for pos in self.positions]}

def remove_position(self, position_index: int):
    """Remove position from portfolio"""
    if 0 <= position_index < len(self.positions):
        removed_position = self.positions.pop(position_index)
        self.last_update = datetime.now()
        logger.info(f'Removed position: {removed_position.instrument}')
    else:
        raise ValueError('Invalid position index')

class RiskAnalyzer:
    """Advanced risk analysis for derivatives portfolios"""

    def __init__(self, confidence_levels: List[float]=None):
        self.confidence_levels = confidence_levels or [0.95, 0.99]
        self.simulation_results = []

    def calculate_var(self, returns: np.ndarray, confidence_level: float=0.95) -> float:
        """Calculate Value at Risk"""
        if len(returns) == 0:
            return 0.0
        return np.percentile(returns, (1 - confidence_level) * 100)

    def calculate_cvar(self, returns: np.ndarray, confidence_level: float=0.95) -> float:
        """Calculate Conditional Value at Risk (Expected Shortfall)"""
        if len(returns) == 0:
            return 0.0
        var_threshold = self.calculate_var(returns, confidence_level)
        tail_losses = returns[returns <= var_threshold]
        return np.mean(tail_losses) if len(tail_losses) > 0 else var_threshold

    def calculate_maximum_drawdown(self, portfolio_values: np.ndarray) -> float:
        """Calculate maximum drawdown"""
        if len(portfolio_values) < 2:
            return 0.0
        running_max = np.maximum.accumulate(portfolio_values)
        drawdowns = (portfolio_values - running_max) / running_max
        return np.min(drawdowns)

    def calculate_portfolio_risk_metrics(self, portfolio: DerivativesPortfolio, historical_returns: np.ndarray=None, benchmark_returns: np.ndarray=None, risk_free_rate: float=0.02) -> RiskMetrics:
        """Calculate comprehensive risk metrics"""
        if historical_returns is None:
            historical_returns = np.random.normal(0.001, 0.02, 252)
        portfolio_value = sum((pos.current_value for pos in portfolio.positions))
        volatility = np.std(historical_returns) * np.sqrt(252)
        var_95 = self.calculate_var(historical_returns, 0.95)
        var_99 = self.calculate_var(historical_returns, 0.99)
        cvar_95 = self.calculate_cvar(historical_returns, 0.95)
        cvar_99 = self.calculate_cvar(historical_returns, 0.99)
        portfolio_values = portfolio_value * (1 + np.cumsum(historical_returns))
        max_drawdown = self.calculate_maximum_drawdown(portfolio_values)
        excess_returns = historical_returns - risk_free_rate / 252
        sharpe_ratio = np.mean(excess_returns) / np.std(historical_returns) * np.sqrt(252) if np.std(historical_returns) > 0 else 0
        downside_returns = historical_returns[historical_returns < 0]
        downside_deviation = np.std(downside_returns) if len(downside_returns) > 0 else np.std(historical_returns)
        sortino_ratio = np.mean(excess_returns) / downside_deviation * np.sqrt(252) if downside_deviation > 0 else 0
        calmar_ratio = np.mean(excess_returns) * 252 / abs(max_drawdown) if max_drawdown != 0 else 0
        beta = 0.0
        if benchmark_returns is not None and len(benchmark_returns) == len(historical_returns):
            covariance = np.cov(historical_returns, benchmark_returns)[0, 1]
            benchmark_variance = np.var(benchmark_returns)
            beta = covariance / benchmark_variance if benchmark_variance > 0 else 0
        return RiskMetrics(portfolio_value=portfolio_value, var_95=var_95 * portfolio_value, var_99=var_99 * portfolio_value, cvar_95=cvar_95 * portfolio_value, cvar_99=cvar_99 * portfolio_value, volatility=volatility, maximum_drawdown=max_drawdown, sharpe_ratio=sharpe_ratio, sortino_ratio=sortino_ratio, calmar_ratio=calmar_ratio, beta=beta)

def calculate_var(self, returns: np.ndarray, confidence_level: float=0.95) -> float:
    """Calculate Value at Risk"""
    if len(returns) == 0:
        return 0.0
    return np.percentile(returns, (1 - confidence_level) * 100)

def calculate_maximum_drawdown(self, portfolio_values: np.ndarray) -> float:
    """Calculate maximum drawdown"""
    if len(portfolio_values) < 2:
        return 0.0
    running_max = np.maximum.accumulate(portfolio_values)
    drawdowns = (portfolio_values - running_max) / running_max
    return np.min(drawdowns)

