def david_shaw_systematic_decision(research_team: dict, computational_finance: dict, trading_systems: dict, risk_control: dict) -> dict:
    """David Shaw's systematic computational decision"""
    details = []
    research_score = research_team['score'] / 10
    model_confidence = computational_finance.get('model_confidence', 0)
    execution_feasibility = trading_systems['score'] / 10
    risk_acceptability = risk_control['score'] / 8
    overall_systematic_edge = model_confidence * 0.35 + research_score * 0.3 + execution_feasibility * 0.2 + risk_acceptability * 0.15
    model_outputs = computational_finance.get('model_outputs', {})
    monte_carlo_prob = model_outputs.get('monte_carlo', {}).get('probability_of_profit', 0.5)
    if overall_systematic_edge > 0.8 and model_confidence > 0.85:
        if monte_carlo_prob > 0.75:
            decision = 'High conviction systematic position'
            details.append('Strong computational edge with high model confidence')
        else:
            decision = 'Moderate systematic position'
            details.append('Good computational signals with moderate probability')
    elif overall_systematic_edge > 0.6:
        decision = 'Systematic position with enhanced monitoring'
        details.append('Adequate systematic edge requiring close monitoring')
    elif execution_feasibility < 0.4:
        decision = 'Pass - execution constraints'
        details.append('Computational edge limited by execution constraints')
    else:
        decision = 'Insufficient systematic edge'
        details.append('Computational models do not indicate sufficient edge')
    expected_sharpe = overall_systematic_edge * 2
    model_complexity = len(model_outputs) * 0.1
    return {'decision': decision, 'overall_systematic_edge': overall_systematic_edge, 'expected_sharpe': expected_sharpe, 'model_complexity': model_complexity, 'details': '; '.join(details)}

def perform_factor_decomposition(metrics: list, financial_line_items: list) -> float:
    """Perform advanced factor decomposition"""
    if not metrics:
        return 0.5
    latest = metrics[0]
    factor_score = 0
    if latest.price_to_book:
        value_score = max(0, 1 - latest.price_to_book / 2)
        factor_score += value_score * 0.3
    if latest.return_on_equity:
        quality_score = min(latest.return_on_equity / 0.2, 1.0)
        factor_score += quality_score * 0.3
    revenues = [item.revenue for item in financial_line_items if item.revenue]
    if len(revenues) >= 4:
        growth_rate = (revenues[0] / revenues[-1]) ** (1 / len(revenues)) - 1
        growth_score = min(growth_rate / 0.15, 1.0)
        factor_score += growth_score * 0.4
    return factor_score

def perform_cross_sectional_analysis(metrics: list, market_cap: float) -> float:
    """Perform cross-sectional ranking analysis"""
    if not metrics:
        return 0.5
    latest = metrics[0]
    ranking_score = 0
    if latest.return_on_equity:
        roe_percentile = min(latest.return_on_equity / 0.25, 1.0)
        ranking_score += roe_percentile * 0.3
    if latest.price_to_earnings and latest.price_to_earnings > 0:
        pe_percentile = max(0, 1 - latest.price_to_earnings / 25)
        ranking_score += pe_percentile * 0.3
    size_factor = min(math.log10(market_cap / 1000000000) / 2, 1.0)
    ranking_score += size_factor * 0.4
    return ranking_score

def integrate_alternative_data(financial_line_items: list) -> float:
    """Integrate alternative data signals"""
    base_fundamentals = 0.5
    alt_data_boost = 0.2
    return min(base_fundamentals + alt_data_boost, 1.0)

def calculate_risk_neutral_valuation(financial_line_items: list, market_cap: float) -> dict:
    """Calculate risk-neutral valuation"""
    if not financial_line_items or not market_cap:
        return {'upside_potential': 0}
    latest = financial_line_items[0]
    if latest.free_cash_flow and latest.free_cash_flow > 0:
        risk_free_rate = 0.03
        risk_neutral_value = latest.free_cash_flow / risk_free_rate
        upside_potential = (risk_neutral_value - market_cap) / market_cap
        return {'upside_potential': max(0, upside_potential)}
    return {'upside_potential': 0}

def analyze_market_microstructure(financial_line_items: list, market_cap: float) -> float:
    """Analyze market microstructure opportunities"""
    liquidity_score = min(market_cap / 10000000000, 1.0)
    revenues = [item.revenue for item in financial_line_items if item.revenue]
    if revenues:
        volatility = calculate_coefficient_of_variation(revenues)
        volatility_score = min(volatility, 1.0)
        return (liquidity_score + volatility_score) / 2
    return liquidity_score

def generate_high_frequency_signals(financial_line_items: list) -> float:
    """Generate high-frequency trading signals"""
    earnings = [item.net_income for item in financial_line_items if item.net_income]
    if len(earnings) >= 8:
        earnings_changes = [earnings[i] - earnings[i + 1] for i in range(len(earnings) - 1)]
        if earnings_changes:
            autocorr = calculate_autocorrelation(earnings_changes, 1)
            return min(abs(autocorr), 1.0)
    return 0.4

def calculate_advanced_var(financial_line_items: list) -> float:
    """Calculate advanced Value-at-Risk"""
    earnings = [item.net_income for item in financial_line_items if item.net_income]
    if len(earnings) >= 8:
        sorted_earnings = sorted(earnings)
        var_index = int(len(sorted_earnings) * 0.05)
        worst_5pct = sorted_earnings[:var_index + 1]
        if worst_5pct and max(earnings) > 0:
            var_loss = (max(earnings) - min(worst_5pct)) / max(earnings)
            return var_loss
    return 0.2

def conduct_comprehensive_stress_testing(financial_line_items: list) -> dict:
    """Conduct comprehensive stress testing"""
    stress_scenarios = ['market_crash', 'recession', 'sector_downturn', 'liquidity_crisis', 'interest_rate_shock']
    passed_tests = 0
    earnings = [item.net_income for item in financial_line_items if item.net_income]
    revenues = [item.revenue for item in financial_line_items if item.revenue]
    if earnings and revenues:
        negative_earnings = sum((1 for e in earnings if e < 0))
        if negative_earnings <= len(earnings) * 0.2:
            passed_tests += 2
        revenue_declines = sum((1 for i in range(len(revenues) - 1) if revenues[i] < revenues[i + 1]))
        if revenue_declines <= len(revenues) * 0.3:
            passed_tests += 2
        if len(earnings) == len(revenues):
            margins = [earnings[i] / revenues[i] if revenues[i] > 0 else 0 for i in range(len(earnings))]
            margin_volatility = calculate_coefficient_of_variation(margins)
            if margin_volatility < 0.5:
                passed_tests += 1
    pass_rate = passed_tests / len(stress_scenarios)
    return {'pass_rate': pass_rate, 'tests_passed': passed_tests, 'total_tests': len(stress_scenarios)}

def calculate_dynamic_hedging_needs(financial_line_items: list) -> float:
    """Calculate dynamic hedging requirements"""
    revenues = [item.revenue for item in financial_line_items if item.revenue]
    earnings = [item.net_income for item in financial_line_items if item.net_income]
    hedging_score = 0
    if revenues:
        revenue_volatility = calculate_coefficient_of_variation(revenues)
        hedging_score += revenue_volatility * 0.5
    if earnings:
        earnings_volatility = calculate_coefficient_of_variation(earnings)
        hedging_score += earnings_volatility * 0.5
    return min(hedging_score, 1.0)

def analyze_accounting_quality(financial_line_items: list) -> dict:
    """Einhorn's forensic accounting analysis"""
    score = 0
    details = []
    red_flags = []
    if not financial_line_items:
        return {'score': 0, 'details': 'No accounting data'}
    revenues = [item.revenue for item in financial_line_items if item.revenue]
    receivables = [item.accounts_receivable for item in financial_line_items if item.accounts_receivable]
    if len(revenues) >= 3 and len(receivables) >= 3:
        recent_dso = receivables[0] / revenues[0] * 365 if revenues[0] > 0 else 0
        older_dso = receivables[-1] / revenues[-1] * 365 if revenues[-1] > 0 else 0
        if recent_dso > older_dso * 1.3:
            red_flags.append('Deteriorating receivables collection')
            score -= 2
        elif recent_dso < older_dso * 1.1:
            score += 1
            details.append('Stable receivables management')
    inventories = [item.inventory for item in financial_line_items if item.inventory]
    if len(inventories) >= 3 and len(revenues) >= 3:
        recent_inventory_turns = revenues[0] / inventories[0] if inventories[0] > 0 else 0
        older_inventory_turns = revenues[-1] / inventories[-1] if inventories[-1] > 0 else 0
        if recent_inventory_turns < older_inventory_turns * 0.8:
            red_flags.append('Deteriorating inventory turns')
            score -= 1
        elif recent_inventory_turns > older_inventory_turns * 1.1:
            score += 1
            details.append('Improving inventory management')
    assets = [item.total_assets for item in financial_line_items if item.total_assets]
    if len(assets) >= 3:
        asset_growth = (assets[0] / assets[-1]) ** (1 / len(assets)) - 1
        revenue_growth = (revenues[0] / revenues[-1]) ** (1 / len(revenues)) - 1 if revenues else 0
        if asset_growth > revenue_growth * 1.5:
            red_flags.append('Asset growth exceeds revenue growth')
            score -= 1
        else:
            score += 1
            details.append('Reasonable asset growth relative to revenue')
    if red_flags:
        details.append(f'Red flags: {'; '.join(red_flags)}')
    return {'score': score, 'details': '; '.join(details), 'red_flags': red_flags}

def analyze_earnings_vs_cash_flow(financial_line_items: list) -> dict:
    """Einhorn's earnings quality through cash flow analysis"""
    score = 0
    details = []
    if not financial_line_items:
        return {'score': 0, 'details': 'No cash flow data'}
    earnings = [item.net_income for item in financial_line_items if item.net_income]
    cash_flows = [item.free_cash_flow for item in financial_line_items if item.free_cash_flow]
    if len(earnings) >= 3 and len(cash_flows) >= 3:
        total_earnings = sum(earnings)
        total_cash_flow = sum(cash_flows)
        if total_cash_flow > total_earnings * 0.8:
            score += 2
            details.append(f'Strong cash conversion: FCF/Earnings = {total_cash_flow / total_earnings:.2f}')
        elif total_cash_flow < total_earnings * 0.5:
            score -= 2
            details.append(f'Poor cash conversion: FCF/Earnings = {total_cash_flow / total_earnings:.2f}')
    if earnings and cash_flows:
        recent_accruals = earnings[0] - cash_flows[0] if len(earnings) > 0 and len(cash_flows) > 0 else 0
        if abs(recent_accruals) > abs(earnings[0]) * 0.3:
            score -= 1
            details.append('High accruals relative to earnings - quality concern')
        else:
            score += 1
            details.append('Reasonable accruals level')
    if cash_flows:
        positive_fcf_years = sum((1 for fcf in cash_flows if fcf > 0))
        if positive_fcf_years == len(cash_flows):
            score += 2
            details.append(f'Consistent cash generation: {positive_fcf_years}/{len(cash_flows)} years')
        elif positive_fcf_years < len(cash_flows) * 0.6:
            score -= 1
            details.append('Inconsistent cash generation')
    return {'score': score, 'details': '; '.join(details)}

def analyze_valuation_disconnect(metrics: list, financial_line_items: list, market_cap: float) -> dict:
    """Einhorn's analysis of valuation vs fundamental reality"""
    score = 0
    details = []
    if not metrics or not financial_line_items or (not market_cap):
        return {'score': 0, 'details': 'No valuation data'}
    latest_metrics = metrics[0]
    latest_financial = financial_line_items[0]
    if latest_metrics.price_to_earnings and latest_metrics.price_to_earnings > 0:
        earnings = [item.net_income for item in financial_line_items if item.net_income and item.net_income > 0]
        if len(earnings) >= 3:
            earnings_growth = (earnings[0] / earnings[-1]) ** (1 / len(earnings)) - 1
            peg_ratio = latest_metrics.price_to_earnings / (earnings_growth * 100) if earnings_growth > 0 else float('inf')
            if peg_ratio < 1.0:
                score += 2
                details.append(f'Attractive PEG ratio: {peg_ratio:.2f}')
            elif peg_ratio > 2.0:
                score -= 2
                details.append(f'Expensive PEG ratio: {peg_ratio:.2f}')
    if latest_metrics.price_to_book:
        if latest_metrics.price_to_book < 1.0:
            score += 1
            details.append(f'Trading below book value: {latest_metrics.price_to_book:.2f} P/B')
        elif latest_metrics.price_to_book > 3.0 and latest_metrics.return_on_equity and (latest_metrics.return_on_equity < 0.15):
            score -= 2
            details.append(f'High P/B with mediocre ROE: {latest_metrics.price_to_book:.2f} P/B, {latest_metrics.return_on_equity:.1%} ROE')
    if latest_financial.total_assets and latest_financial.total_debt:
        tangible_book = latest_financial.total_assets - latest_financial.total_debt
        if tangible_book > market_cap:
            score += 2
            details.append('Trading below tangible asset value')
    return {'score': score, 'details': '; '.join(details)}

def identify_red_flags(financial_line_items: list) -> dict:
    """Einhorn's red flag identification system"""
    score = 0
    details = []
    flags = []
    if not financial_line_items:
        return {'score': 0, 'details': 'No data for red flag analysis'}
    assets = [item.total_assets for item in financial_line_items if item.total_assets]
    revenues = [item.revenue for item in financial_line_items if item.revenue]
    if len(assets) >= 3 and len(revenues) >= 3:
        asset_cagr = (assets[0] / assets[-1]) ** (1 / len(assets)) - 1
        revenue_cagr = (revenues[0] / revenues[-1]) ** (1 / len(revenues)) - 1
        if asset_cagr > revenue_cagr + 0.1:
            flags.append('Asset growth exceeds revenue growth')
            score -= 2
    margins = []
    for item in financial_line_items:
        if item.revenue and item.operating_income and (item.revenue > 0):
            margins.append(item.operating_income / item.revenue)
    if len(margins) >= 3:
        margin_trend = margins[0] - margins[-1]
        if margin_trend < -0.05:
            flags.append('Significant margin compression')
            score -= 1
    cash_flows = [item.free_cash_flow for item in financial_line_items if item.free_cash_flow]
    if cash_flows:
        negative_years = sum((1 for fcf in cash_flows if fcf < 0))
        if negative_years > len(cash_flows) * 0.4:
            flags.append('Inconsistent cash generation')
            score -= 1
    receivables = [item.accounts_receivable for item in financial_line_items if item.accounts_receivable]
    if len(receivables) >= 3 and len(revenues) >= 3:
        receivables_growth = (receivables[0] / receivables[-1]) ** (1 / len(receivables)) - 1
        revenue_growth = (revenues[0] / revenues[-1]) ** (1 / len(revenues)) - 1
        if receivables_growth > revenue_growth + 0.15:
            flags.append('Receivables growing faster than revenue')
            score -= 1
    if not flags:
        score += 2
        details.append('No major red flags identified')
    else:
        details.append(f'Red flags: {'; '.join(flags)}')
    return {'score': score, 'details': '; '.join(details), 'flags': flags}

def calculate_fundamental_value(financial_line_items: list, market_cap: float) -> dict:
    """Einhorn's fundamental valuation analysis"""
    score = 0
    details = []
    if not financial_line_items or not market_cap:
        return {'score': 0, 'details': 'No fundamental data'}
    latest = financial_line_items[0]
    if latest.total_assets and latest.total_debt:
        book_value = latest.total_assets - latest.total_debt
        pb_ratio = market_cap / book_value if book_value > 0 else float('inf')
        if pb_ratio < 1.0:
            score += 3
            details.append(f'Trading below book value: {pb_ratio:.2f} P/B')
        elif pb_ratio < 1.5:
            score += 1
            details.append(f'Reasonable book value: {pb_ratio:.2f} P/B')
    earnings = [item.net_income for item in financial_line_items if item.net_income and item.net_income > 0]
    if earnings:
        avg_earnings = sum(earnings) / len(earnings)
        pe_ratio = market_cap / avg_earnings
        if pe_ratio < 12:
            score += 2
            details.append(f'Low earnings multiple: {pe_ratio:.1f} P/E')
        elif pe_ratio > 25:
            score -= 1
            details.append(f'High earnings multiple: {pe_ratio:.1f} P/E')
    if latest.free_cash_flow and latest.free_cash_flow > 0:
        fcf_yield = latest.free_cash_flow / market_cap
        if fcf_yield > 0.08:
            score += 2
            details.append(f'Attractive FCF yield: {fcf_yield:.1%}')
        elif fcf_yield < 0.03:
            score -= 1
            details.append(f'Low FCF yield: {fcf_yield:.1%}')
    return {'score': score, 'details': '; '.join(details)}

def calculate_earnings_yield(financial_line_items: list, market_cap: float) -> dict:
    """Calculate Greenblatt's earnings yield (EBIT / Enterprise Value)"""
    score = 0
    details = []
    if not financial_line_items or not market_cap:
        return {'score': 0, 'details': 'No data for earnings yield', 'value': None}
    latest = financial_line_items[0]
    ebit = latest.operating_income if latest.operating_income else 0
    total_debt = latest.total_debt if latest.total_debt else 0
    cash = latest.current_assets * 0.2 if latest.current_assets else 0
    enterprise_value = market_cap + total_debt - cash
    if enterprise_value > 0 and ebit > 0:
        earnings_yield = ebit / enterprise_value
        if earnings_yield > 0.15:
            score = 10
            details.append(f'Exceptional earnings yield: {earnings_yield:.1%}')
        elif earnings_yield > 0.12:
            score = 8
            details.append(f'Strong earnings yield: {earnings_yield:.1%}')
        elif earnings_yield > 0.09:
            score = 6
            details.append(f'Good earnings yield: {earnings_yield:.1%}')
        elif earnings_yield > 0.06:
            score = 4
            details.append(f'Fair earnings yield: {earnings_yield:.1%}')
        else:
            score = 2
            details.append(f'Low earnings yield: {earnings_yield:.1%}')
    else:
        earnings_yield = 0
        details.append('No positive earnings yield')
    return {'score': score, 'value': earnings_yield, 'details': '; '.join(details)}

def calculate_return_on_capital(financial_line_items: list) -> dict:
    """Calculate Greenblatt's return on invested capital"""
    score = 0
    details = []
    if not financial_line_items:
        return {'score': 0, 'details': 'No data for ROIC', 'value': None}
    latest = financial_line_items[0]
    ebit = latest.operating_income if latest.operating_income else 0
    current_assets = latest.current_assets if latest.current_assets else 0
    current_liabilities = latest.current_liabilities if latest.current_liabilities else 0
    working_capital = current_assets - current_liabilities
    total_assets = latest.total_assets if latest.total_assets else 0
    invested_capital = max(working_capital + (total_assets - current_assets), total_assets * 0.5)
    if invested_capital > 0 and ebit > 0:
        roic = ebit / invested_capital
        if roic > 0.25:
            score = 10
            details.append(f'Exceptional ROIC: {roic:.1%}')
        elif roic > 0.2:
            score = 8
            details.append(f'Strong ROIC: {roic:.1%}')
        elif roic > 0.15:
            score = 6
            details.append(f'Good ROIC: {roic:.1%}')
        elif roic > 0.1:
            score = 4
            details.append(f'Fair ROIC: {roic:.1%}')
        else:
            score = 2
            details.append(f'Low ROIC: {roic:.1%}')
    else:
        roic = 0
        details.append('No positive return on capital')
    return {'score': score, 'value': roic, 'details': '; '.join(details)}

def calculate_magic_formula_rank(earnings_yield: dict, return_on_capital: dict) -> dict:
    """Combine earnings yield and ROIC for Magic Formula ranking"""
    score = 0
    details = []
    ey_score = earnings_yield.get('score', 0)
    roic_score = return_on_capital.get('score', 0)
    combined_score = (ey_score + roic_score) / 2
    if combined_score >= 9:
        score = 10
        details.append('Magic Formula: Top tier (high ROIC + high earnings yield)')
    elif combined_score >= 7:
        score = 8
        details.append('Magic Formula: Strong candidate')
    elif combined_score >= 5:
        score = 6
        details.append('Magic Formula: Decent candidate')
    else:
        score = 3
        details.append('Magic Formula: Below average')
    ey_val = earnings_yield.get('value', 0)
    roic_val = return_on_capital.get('value', 0)
    if ey_val > 0.12 and roic_val > 0.2:
        score = min(10, score + 2)
        details.append('Exceptional Magic Formula combination')
    return {'score': score, 'combined_score': combined_score, 'details': '; '.join(details)}

def analyze_business_quality_greenblatt(metrics: list, financial_line_items: list) -> dict:
    """Greenblatt's additional quality checks beyond Magic Formula"""
    score = 0
