def buffett_valuation(financial_line_items: list, market_cap: float) -> dict:
    """Buffett's 'fair price for wonderful business' approach"""
    score = 0
    details = []
    if not financial_line_items or not market_cap:
        return {'score': 0, 'details': 'No valuation data'}
    latest = financial_line_items[0]
    earnings = [item.net_income for item in financial_line_items if item.net_income and item.net_income > 0]
    if not earnings:
        return {'score': 0, 'details': 'No positive earnings for valuation'}
    if latest.free_cash_flow and latest.free_cash_flow > 0:
        fcf_yield = latest.free_cash_flow / market_cap
        if fcf_yield > 0.08:
            score += 3
            details.append(f'Attractive FCF yield: {fcf_yield:.1%}')
        elif fcf_yield > 0.05:
            score += 1
            details.append(f'Reasonable FCF yield: {fcf_yield:.1%}')
    if latest.net_income and latest.net_income > 0:
        pe_ratio = market_cap / latest.net_income
        if pe_ratio < 15:
            score += 2
            details.append(f'Reasonable valuation: {pe_ratio:.1f} P/E')
        elif pe_ratio < 25:
            score += 1
            details.append(f'Fair valuation: {pe_ratio:.1f} P/E')
    return {'score': score, 'details': '; '.join(details)}

def analyze_downside_protection(financial_line_items: list, market_cap: float) -> dict:
    """Klarman's obsession with downside protection"""
    score = 0
    details = []
    if not financial_line_items or not market_cap:
        return {'score': 0, 'details': 'No data for downside analysis'}
    latest = financial_line_items[0]
    total_assets = latest.total_assets if latest.total_assets else 0
    total_debt = latest.total_debt if latest.total_debt else 0
    if total_assets > 0:
        asset_coverage = total_assets / market_cap
        if asset_coverage > 2.0:
            score += 3
            details.append(f'Strong asset coverage: {asset_coverage:.1f}x market cap')
        elif asset_coverage > 1.5:
            score += 2
            details.append(f'Adequate asset coverage: {asset_coverage:.1f}x market cap')
    current_assets = latest.current_assets if latest.current_assets else 0
    current_liabilities = latest.current_liabilities if latest.current_liabilities else 0
    cash = latest.cash_and_equivalents if latest.cash_and_equivalents else 0
    liquidation_value = cash + (current_assets - cash) * 0.7
    net_liquidation = liquidation_value - current_liabilities - total_debt
    if net_liquidation > 0:
        liquidation_ratio = net_liquidation / market_cap
        if liquidation_ratio > 0.5:
            score += 4
            details.append(f'Exceptional liquidation protection: {liquidation_ratio:.1%}')
        elif liquidation_ratio > 0.2:
            score += 2
            details.append(f'Good liquidation value: {liquidation_ratio:.1%}')
    earnings = [item.net_income for item in financial_line_items if item.net_income]
    if earnings:
        worst_earnings = min(earnings)
        if worst_earnings > 0:
            score += 2
            details.append('No losses in available periods')
        elif worst_earnings > -market_cap * 0.05:
            score += 1
            details.append('Limited downside from worst historical performance')
    return {'score': score, 'details': '; '.join(details)}

def analyze_asymmetric_risk_reward(metrics: list, financial_line_items: list, market_cap: float) -> dict:
    """Klarman's focus on asymmetric opportunities"""
    score = 0
    details = []
    if not financial_line_items or not market_cap:
        return {'score': 0, 'details': 'No data for asymmetric analysis'}
    latest = financial_line_items[0]
    earnings = [item.net_income for item in financial_line_items if item.net_income and item.net_income > 0]
    if earnings:
        avg_earnings = sum(earnings) / len(earnings)
        normalized_pe = market_cap / avg_earnings if avg_earnings > 0 else 0
        if normalized_pe < 12 and latest.total_assets and (latest.total_assets > market_cap):
            score += 3
            details.append(f'Asymmetric setup: {normalized_pe:.1f} P/E with asset backing')
    if latest.free_cash_flow and latest.free_cash_flow > 0:
        fcf_yield = latest.free_cash_flow / market_cap
        debt_ratio = latest.total_debt / latest.total_assets if latest.total_assets else 1
        if fcf_yield > 0.1 and debt_ratio < 0.3:
            score += 2
            details.append(f'Strong FCF yield ({fcf_yield:.1%}) with low debt')
    revenues = [item.revenue for item in financial_line_items if item.revenue]
    if len(revenues) >= 3:
        recent_growth = revenues[0] / revenues[1] - 1
        if recent_growth > 0.1:
            score += 1
            details.append(f'Potential catalyst: {recent_growth:.1%} recent revenue growth')
    return {'score': score, 'details': '; '.join(details)}

def analyze_contrarian_opportunity(metrics: list, financial_line_items: list) -> dict:
    """Klarman's contrarian approach to investing"""
    score = 0
    details = []
    if not metrics or not financial_line_items:
        return {'score': 0, 'details': 'No data for contrarian analysis'}
    latest_metrics = metrics[0]
    if latest_metrics.price_to_book and latest_metrics.price_to_book < 1.0:
        score += 2
        details.append(f'Contrarian P/B: {latest_metrics.price_to_book:.2f}')
    if latest_metrics.price_to_earnings and latest_metrics.price_to_earnings < 10:
        score += 2
        details.append(f'Contrarian P/E: {latest_metrics.price_to_earnings:.1f}')
    earnings = [item.net_income for item in financial_line_items if item.net_income]
    if len(earnings) >= 3:
        recent_earnings = earnings[0]
        historical_avg = sum(earnings[1:]) / len(earnings[1:])
        if recent_earnings < historical_avg * 0.7 and recent_earnings > 0:
            score += 2
            details.append('Potential temporary earnings depression')
    if latest_metrics.current_ratio and latest_metrics.current_ratio < 1.2:
        score += 1
        details.append('Potential distress situation for contrarian investment')
    return {'score': score, 'details': '; '.join(details)}

def analyze_balance_sheet_fortress(financial_line_items: list) -> dict:
    """Klarman's requirement for fortress balance sheets"""
    score = 0
    details = []
    if not financial_line_items:
        return {'score': 0, 'details': 'No balance sheet data'}
    latest = financial_line_items[0]
    cash = latest.cash_and_equivalents if latest.cash_and_equivalents else 0
    current_assets = latest.current_assets if latest.current_assets else 0
    current_liabilities = latest.current_liabilities if latest.current_liabilities else 0
    if current_liabilities > 0:
        current_ratio = current_assets / current_liabilities
        if current_ratio > 2.0:
            score += 2
            details.append(f'Strong liquidity: {current_ratio:.1f} current ratio')
    total_debt = latest.total_debt if latest.total_debt else 0
    shareholders_equity = latest.shareholders_equity if latest.shareholders_equity else 0
    if shareholders_equity > 0:
        debt_to_equity = total_debt / shareholders_equity
        if debt_to_equity < 0.3:
            score += 3
            details.append(f'Conservative debt: {debt_to_equity:.2f} D/E')
        elif debt_to_equity < 0.5:
            score += 1
            details.append(f'Moderate debt: {debt_to_equity:.2f} D/E')
    working_capital = current_assets - current_liabilities
    if working_capital > 0 and latest.total_assets:
        wc_ratio = working_capital / latest.total_assets
        if wc_ratio > 0.2:
            score += 2
            details.append(f'Strong working capital: {wc_ratio:.1%} of assets')
    if latest.operating_income and total_debt > 0:
        estimated_interest = total_debt * 0.05
        if latest.operating_income > estimated_interest * 5:
            score += 2
            details.append('Strong interest coverage capability')
    return {'score': score, 'details': '; '.join(details)}

def calculate_klarman_margin_of_safety(financial_line_items: list, market_cap: float) -> dict:
    """Klarman's conservative margin of safety calculation"""
    score = 0
    details = []
    if not financial_line_items or not market_cap:
        return {'score': 0, 'details': 'No data for margin of safety'}
    latest = financial_line_items[0]
    total_assets = latest.total_assets if latest.total_assets else 0
    total_debt = latest.total_debt if latest.total_debt else 0
    conservative_asset_value = total_assets * 0.7
    net_asset_value = conservative_asset_value - total_debt
    if net_asset_value > 0:
        asset_margin = (net_asset_value - market_cap) / market_cap
        if asset_margin > 0.5:
            score += 3
            details.append(f'Excellent asset margin of safety: {asset_margin:.1%}')
        elif asset_margin > 0.2:
            score += 2
            details.append(f'Good asset margin of safety: {asset_margin:.1%}')
    earnings = [item.net_income for item in financial_line_items if item.net_income and item.net_income > 0]
    if earnings:
        avg_earnings = sum(earnings) / len(earnings)
        conservative_earnings_value = avg_earnings * 10
        earnings_margin = (conservative_earnings_value - market_cap) / market_cap
        if earnings_margin > 0.3:
            score += 2
            details.append(f'Earnings margin of safety: {earnings_margin:.1%}')
    if latest.free_cash_flow and latest.free_cash_flow > 0:
        fcf_value = latest.free_cash_flow * 12
        fcf_margin = (fcf_value - market_cap) / market_cap
        if fcf_margin > 0.25:
            score += 2
            details.append(f'FCF margin of safety: {fcf_margin:.1%}')
    return {'score': score, 'details': '; '.join(details)}

def analyze_contrarian_setup(metrics: list, financial_line_items: list, market_cap: float) -> dict:
    """Miller's contrarian opportunity identification"""
    score = 0
    details = []
    if not metrics or not financial_line_items:
        return {'score': 0, 'details': 'No contrarian data'}
    latest_metrics = metrics[0]
    if latest_metrics.price_to_earnings:
        if latest_metrics.price_to_earnings < 8:
            score += 3
            details.append(f'Extreme valuation contrarian setup: {latest_metrics.price_to_earnings:.1f} P/E')
        elif latest_metrics.price_to_earnings < 12:
            score += 2
            details.append(f'Attractive contrarian valuation: {latest_metrics.price_to_earnings:.1f} P/E')
    if latest_metrics.price_to_book and latest_metrics.price_to_book < 1.0:
        score += 2
        details.append(f'Market pessimism: {latest_metrics.price_to_book:.2f} P/B below 1.0')
    earnings = [item.net_income for item in financial_line_items if item.net_income]
    revenues = [item.revenue for item in financial_line_items if item.revenue]
    if len(earnings) >= 5 and len(revenues) >= 5:
        recent_earnings_decline = earnings[0] < earnings[2]
        revenue_resilience = revenues[0] > revenues[2] * 0.9
        if recent_earnings_decline and revenue_resilience:
            score += 2
            details.append('Temporary earnings pressure with revenue resilience - contrarian opportunity')
    rd_vals = [item.research_and_development for item in financial_line_items if item.research_and_development]
    if rd_vals and revenues:
        rd_intensity = sum(rd_vals[:3]) / sum(revenues[:3]) if len(revenues) >= 3 else 0
        if rd_intensity > 0.1:
            score += 1
            details.append(f'High R&D investment for future positioning: {rd_intensity:.1%}')
    return {'score': score, 'details': '; '.join(details)}

def analyze_technology_value_potential(financial_line_items: list, market_cap: float) -> dict:
    """Miller's technology value analysis"""
    score = 0
    details = []
    if not financial_line_items or not market_cap:
        return {'score': 0, 'details': 'No technology data'}
    latest = financial_line_items[0]
    if latest.total_assets and latest.revenue:
        asset_turnover = latest.revenue / latest.total_assets
        if asset_turnover > 1.0:
            score += 2
            details.append(f'Asset-efficient model: {asset_turnover:.1f}x turnover')
    revenues = [item.revenue for item in financial_line_items if item.revenue]
    margins = []
    for item in financial_line_items:
        if item.operating_income and item.revenue and (item.revenue > 0):
            margins.append(item.operating_income / item.revenue)
    if len(revenues) >= 3 and len(margins) >= 3:
        revenue_growth = (revenues[0] / revenues[-1]) ** (1 / len(revenues)) - 1
        margin_expansion = margins[0] - margins[-1]
        if revenue_growth > 0.1 and margin_expansion > 0.02:
            score += 3
            details.append(f'Scalable growth: {revenue_growth:.1%} revenue CAGR with margin expansion')
    rd_vals = [item.research_and_development for item in financial_line_items if item.research_and_development]
    if rd_vals and revenues:
        rd_to_revenue = rd_vals[0] / revenues[0] if revenues[0] > 0 else 0
        if 0.05 <= rd_to_revenue <= 0.2:
            score += 1
            details.append(f'Strategic R&D investment: {rd_to_revenue:.1%} of revenue')
    if latest.free_cash_flow and latest.free_cash_flow > 0:
        fcf_margin = latest.free_cash_flow / latest.revenue if latest.revenue > 0 else 0
        if fcf_margin > 0.2:
            score += 2
            details.append(f'High-margin business model: {fcf_margin:.1%} FCF margin')
    return {'score': score, 'details': '; '.join(details)}

def analyze_long_term_growth_drivers(financial_line_items: list) -> dict:
    """Miller's long-term growth potential analysis"""
    score = 0
    details = []
    if not financial_line_items:
        return {'score': 0, 'details': 'No growth data'}
    revenues = [item.revenue for item in financial_line_items if item.revenue]
    if len(revenues) >= 5:
        growth_years = sum((1 for i in range(len(revenues) - 1) if revenues[i] >= revenues[i + 1]))
        if growth_years >= len(revenues) * 0.8:
            revenue_cagr = (revenues[0] / revenues[-1]) ** (1 / len(revenues)) - 1
            score += 2
            details.append(f'Consistent growth track record: {revenue_cagr:.1%} CAGR')
    rd_vals = [item.research_and_development for item in financial_line_items if item.research_and_development]
    if rd_vals and len(rd_vals) >= 3:
        rd_growth = (rd_vals[0] / rd_vals[-1]) ** (1 / len(rd_vals)) - 1
        if rd_growth > 0.1:
            score += 1
            details.append(f'Growing R&D investment: {rd_growth:.1%} CAGR')
    if latest.total_assets and latest.shareholders_equity:
        leverage_capacity = (latest.total_assets - latest.shareholders_equity) / latest.shareholders_equity
        if leverage_capacity < 0.5:
            score += 1
            details.append('Balance sheet capacity for growth investments')
    fcf_vals = [item.free_cash_flow for item in financial_line_items if item.free_cash_flow]
    if fcf_vals and revenues:
        positive_fcf_years = sum((1 for fcf in fcf_vals if fcf > 0))
        if positive_fcf_years >= len(fcf_vals) * 0.8:
            score += 2
            details.append(f'Self-funding growth capability: {positive_fcf_years}/{len(fcf_vals)} positive FCF years')
    return {'score': score, 'details': '; '.join(details)}

def identify_market_misperceptions(metrics: list, financial_line_items: list) -> dict:
    """Miller's market misperception identification"""
    score = 0
    details = []
    if not metrics or not financial_line_items:
        return {'score': 0, 'details': 'No misperception data'}
    latest_metrics = metrics[0]
    if latest_metrics.return_on_equity and latest_metrics.return_on_equity > 0.15 and latest_metrics.price_to_earnings and (latest_metrics.price_to_earnings < 15):
        score += 3
        details.append(f'Quality-value disconnect: {latest_metrics.return_on_equity:.1%} ROE at {latest_metrics.price_to_earnings:.1f} P/E')
    earnings = [item.net_income for item in financial_line_items if item.net_income and item.net_income > 0]
    revenues = [item.revenue for item in financial_line_items if item.revenue]
    if len(earnings) >= 5 and len(revenues) >= 5:
        historical_earnings_growth = (earnings[-1] / earnings[-3]) ** (1 / 2) - 1
        recent_earnings_decline = earnings[0] < earnings[1]
        revenue_growth = (revenues[0] / revenues[-1]) ** (1 / len(revenues)) - 1
        if historical_earnings_growth > 0.15 and recent_earnings_decline and (revenue_growth > 0.05):
            score += 2
            details.append('Historical growth company with temporary earnings setback')
    if latest_metrics.price_to_book and latest_metrics.price_to_book < 1.2:
        latest_financial = financial_line_items[0]
        if latest_financial.total_assets and latest_financial.total_debt:
            tangible_assets = latest_financial.total_assets - latest_financial.total_debt
            if tangible_assets > 0:
                score += 1
                details.append(f'Asset value misperception: {latest_metrics.price_to_book:.2f} P/B')
    return {'score': score, 'details': '; '.join(details)}

def evaluate_concentration_candidate(metrics: list, financial_line_items: list, market_cap: float) -> dict:
    """Miller's concentrated portfolio candidate evaluation"""
    score = 0
    details = []
    if not metrics or not financial_line_items or (not market_cap):
        return {'score': 0, 'details': 'No concentration data'}
    latest_metrics = metrics[0]
    if latest_metrics.return_on_equity and latest_metrics.return_on_equity > 0.18:
        score += 2
        details.append(f'Strong competitive position: {latest_metrics.return_on_equity:.1%} ROE')
    if latest_metrics.price_to_earnings and latest_metrics.price_to_earnings < 12:
        earnings = [item.net_income for item in financial_line_items if item.net_income and item.net_income > 0]
        if earnings:
            upside_potential = 18 * earnings[0] / market_cap - 1
            if upside_potential > 0.5:
                score += 3
                details.append(f'Significant upside potential: {upside_potential:.1%}')
    revenues = [item.revenue for item in financial_line_items if item.revenue]
    if revenues and len(revenues) >= 7:
        revenue_consistency = len([r for r in revenues if r > min(revenues) * 1.1]) / len(revenues)
        if revenue_consistency > 0.8:
            score += 2
            details.append('Durable business model with consistent revenue growth')
    if latest_metrics.return_on_invested_capital and latest_metrics.return_on_invested_capital > 0.12:
        score += 1
        details.append(f'Strong capital allocation: {latest_metrics.return_on_invested_capital:.1%} ROIC')
    return {'score': score, 'details': '; '.join(details)}

def analyze_net_net_value(financial_line_items: list, market_cap: float) -> dict:
    """Graham's net-net working capital analysis"""
    score = 0
    details = []
    if not financial_line_items or not market_cap:
        return {'score': 0, 'details': 'No data for net-net analysis'}
    latest = financial_line_items[0]
    current_assets = latest.current_assets if latest.current_assets else 0
    current_liabilities = latest.current_liabilities if latest.current_liabilities else 0
    total_debt = latest.total_debt if latest.total_debt else 0
    cash = latest.cash_and_equivalents if latest.cash_and_equivalents else 0
    receivables = latest.accounts_receivable * 0.85 if latest.accounts_receivable else 0
    inventory = latest.inventory * 0.5 if latest.inventory else 0
    liquidation_value = cash + receivables + inventory
    net_net_value = liquidation_value - current_liabilities - total_debt
    if net_net_value > 0:
        nnwc_ratio = net_net_value / market_cap
        if nnwc_ratio > 0.5:
            score += 5
            details.append(f'Exceptional net-net: {nnwc_ratio:.1%} of market cap')
        elif nnwc_ratio > 0.2:
            score += 3
            details.append(f'Good net-net value: {nnwc_ratio:.1%} of market cap')
        else:
            score += 1
            details.append(f'Some net-net value: {nnwc_ratio:.1%} of market cap')
    else:
        details.append('No net-net working capital protection')
    return {'score': score, 'details': '; '.join(details)}

def analyze_defensive_investor_criteria(metrics: list, financial_line_items: list) -> dict:
    """Graham's 10 criteria for defensive investors"""
    score = 0
    criteria_met = 0
    details = []
    if not metrics or not financial_line_items:
        return {'score': 0, 'details': 'No data for defensive criteria'}
    latest_metrics = metrics[0]
    latest_financial = financial_line_items[0]
    if latest_financial.revenue and latest_financial.revenue > 100000000:
        criteria_met += 1
        details.append('✓ Adequate size')
    if latest_metrics.current_ratio and latest_metrics.current_ratio > 2.0:
        criteria_met += 1
        details.append(f'✓ Strong current ratio: {latest_metrics.current_ratio:.1f}')
    earnings_history = [item.net_income for item in financial_line_items if item.net_income]
    if len(earnings_history) >= 5:
        positive_years = sum((1 for e in earnings_history if e > 0))
        if positive_years == len(earnings_history):
            criteria_met += 1
            details.append(f'✓ Earnings stability: {positive_years}/{len(earnings_history)} positive years')
    if latest_financial.net_income and latest_financial.net_income > 0:
        criteria_met += 0.5
        details.append('? Dividend assumption based on profitability')
    if len(earnings_history) >= 5:
        if earnings_history[0] > earnings_history[-1] * 1.33:
            criteria_met += 1
            details.append('✓ Adequate earnings growth')
    if latest_metrics.price_to_earnings and latest_metrics.price_to_earnings < 15:
        criteria_met += 1
        details.append(f'✓ Reasonable P/E: {latest_metrics.price_to_earnings:.1f}')
    if latest_metrics.price_to_book and latest_metrics.price_to_book < 1.5:
        criteria_met += 1
        details.append(f'✓ Conservative P/B: {latest_metrics.price_to_book:.1f}')
    if latest_metrics.debt_to_equity and latest_metrics.debt_to_equity < 0.5:
        criteria_met += 1
        details.append(f'✓ Low debt: {latest_metrics.debt_to_equity:.2f} D/E')
    score = criteria_met / 8 * 10
    return {'score': score, 'criteria_met': criteria_met, 'details': '; '.join(details)}

def calculate_margin_of_safety(metrics: list, financial_line_items: list, market_cap: float) -> dict:
    """Graham's margin of safety calculation"""
    score = 0
    details = []
    if not metrics or not financial_line_items or (not market_cap):
        return {'score': 0, 'details': 'No data for margin of safety'}
    latest_metrics = metrics[0]
    latest_financial = financial_line_items[0]
    if latest_financial.shareholders_equity and latest_financial.shareholders_equity > 0:
        book_value = latest_financial.shareholders_equity
        pb_ratio = market_cap / book_value
        if pb_ratio < 0.67:
            score += 4
            details.append(f'Excellent margin of safety: {pb_ratio:.2f} P/B')
        elif pb_ratio < 1.0:
            score += 2
            details.append(f'Good margin of safety: {pb_ratio:.2f} P/B')
    if latest_financial.net_income and latest_financial.net_income > 0:
        pe_ratio = market_cap / latest_financial.net_income
        if pe_ratio < 10:
            score += 3
            details.append(f'Conservative earnings multiple: {pe_ratio:.1f} P/E')
        elif pe_ratio < 15:
            score += 1
            details.append(f'Reasonable earnings multiple: {pe_ratio:.1f} P/E')
    if latest_financial.total_assets and latest_financial.total_debt:
        asset_coverage = latest_financial.total_assets / latest_financial.total_debt
        if asset_coverage > 2.0:
            score += 2
            details.append(f'Strong asset coverage: {asset_coverage:.1f}x')
    return {'score': score, 'details': '; '.join(details)}

def analyze_earnings_stability(financial_line_items: list) -> dict:
    """Graham emphasized earnings stability over growth"""
    score = 0
    details = []
    earnings = [item.net_income for item in financial_line_items if item.net_income]
    if len(earnings) < 3:
        return {'score': 0, 'details': 'Insufficient earnings history'}
    losses = sum((1 for e in earnings if e < 0))
    if losses == 0:
        score += 3
        details.append('No losses in available periods')
    elif losses <= 1:
        score += 1
        details.append(f'Only {losses} loss year')
    if earnings:
        avg_earnings = sum(earnings) / len(earnings)
        volatility = sum(((e - avg_earnings) ** 2 for e in earnings)) / len(earnings)
        coefficient_of_variation = volatility ** 0.5 / abs(avg_earnings) if avg_earnings != 0 else float('inf')
        if coefficient_of_variation < 0.3:
            score += 2
            details.append(f'Low earnings volatility: {coefficient_of_variation:.2f} CV')
    return {'score': score, 'details': '; '.join(details)}

def analyze_asset_protection(financial_line_items: list, market_cap: float) -> dict:
    """Graham's focus on asset protection for bondholders and stockholders"""
    score = 0
    details = []
    if not financial_line_items or not market_cap:
        return {'score': 0, 'details': 'No asset data'}
    latest = financial_line_items[0]
    if latest.current_assets and latest.current_liabilities:
        working_capital = latest.current_assets - latest.current_liabilities
        if working_capital > 0:
            wc_ratio = working_capital / market_cap
            if wc_ratio > 0.3:
                score += 2
                details.append(f'Strong working capital: {wc_ratio:.1%} of market cap')
    if latest.total_assets and latest.total_debt:
        if latest.total_debt == 0:
            score += 3
            details.append('Debt-free company')
        else:
            debt_ratio = latest.total_debt / latest.total_assets
            if debt_ratio < 0.3:
                score += 2
                details.append(f'Conservative debt: {debt_ratio:.1%} of assets')
    if latest.shareholders_equity:
        tangible_equity = latest.shareholders_equity
        if tangible_equity > market_cap * 0.5:
            score += 2
            details.append('Trading below tangible book value')
    return {'score': score, 'details': '; '.join(details)}

def analyze_risk_factors(metrics: list, financial_line_items: list, market_cap: float) -> dict:
    """Marks' comprehensive risk assessment framework"""
    score = 0
    details = []
    risk_factors = []
    if not metrics or not financial_line_items:
        return {'score': 0, 'details': 'No data for risk analysis'}
    latest_metrics = metrics[0]
    latest_financial = financial_line_items[0]
    if latest_metrics.debt_to_equity:
        if latest_metrics.debt_to_equity < 0.3:
            score += 2
            details.append(f'Low leverage risk: {latest_metrics.debt_to_equity:.2f} D/E')
        elif latest_metrics.debt_to_equity > 1.0:
            risk_factors.append('High leverage risk')
            score -= 1
    earnings = [item.net_income for item in financial_line_items if item.net_income]
    if earnings and len(earnings) >= 5:
        earnings_volatility = (max(earnings) - min(earnings)) / max(abs(max(earnings)), abs(min(earnings)))
        if earnings_volatility < 0.5:
            score += 2
            details.append(f'Stable earnings pattern: {earnings_volatility:.2f} volatility')
        else:
            risk_factors.append('High earnings volatility')
    if latest_metrics.current_ratio:
        if latest_metrics.current_ratio > 1.5:
            score += 1
            details.append(f'Adequate liquidity: {latest_metrics.current_ratio:.1f} current ratio')
        elif latest_metrics.current_ratio < 1.0:
            risk_factors.append('Liquidity concerns')
            score -= 2
    revenues = [item.revenue for item in financial_line_items if item.revenue]
    if revenues and len(revenues) >= 5:
        revenue_trend = sum((1 for i in range(len(revenues) - 1) if revenues[i] >= revenues[i + 1]))
        if revenue_trend >= len(revenues) * 0.7:
            score += 1
            details.append('Sustainable revenue pattern')
        else:
            risk_factors.append('Declining revenue trend')
    margins = [item.operating_margin for item in financial_line_items if item.operating_margin]
    if margins and len(margins) >= 3:
        margin_trend = margins[0] - margins[-1]
        if margin_trend > 0.02:
            score += 1
            details.append('Improving margin profile')
        elif margin_trend < -0.05:
            risk_factors.append('Margin compression risk')
            score -= 1
    if risk_factors:
        details.append(f'Risk factors: {'; '.join(risk_factors)}')
    return {'score': score, 'details': '; '.join(details), 'risk_factors': risk_factors}

def analyze_cycle_position(metrics: list, financial_line_items: list) -> dict:
    """Marks' cycle awareness analysis"""
    score = 0
    details = []
    if not metrics or not financial_line_items:
        return {'score': 0, 'details': 'No cycle data'}
    revenues = [item.revenue for item in financial_line_items if item.revenue]
    if len(revenues) >= 5:
        recent_growth = (revenues[0] / revenues[2]) ** (1 / 2) - 1
        longer_growth = (revenues[0] / revenues[-1]) ** (1 / len(revenues)) - 1
        if recent_growth < longer_growth * 0.5:
            score += 2
            details.append('Potential cyclical trough - contrarian opportunity')
        elif recent_growth > longer_growth * 2:
            score -= 1
            details.append('Potential cyclical peak - exercise caution')
    margins = [item.operating_margin for item in financial_line_items if item.operating_margin]
    if len(margins) >= 5:
        current_margin = margins[0]
        avg_margin = sum(margins) / len(margins)
        if current_margin < avg_margin * 0.8:
            score += 1
            details.append('Below-average margins suggest cycle opportunity')
    roe_vals = [m.return_on_equity for m in metrics if m.return_on_equity]
    if len(roe_vals) >= 5:
        current_roe = roe_vals[0]
        avg_roe = sum(roe_vals) / len(roe_vals)
        if current_roe < avg_roe * 0.7:
            score += 2
            details.append('Depressed ROE suggests cyclical opportunity')
    return {'score': score, 'details': '; '.join(details)}

def apply_second_level_thinking(metrics: list, financial_line_items: list, market_cap: float) -> dict:
    """Marks' second-level thinking analysis"""
    score = 0
    details = []
    if not metrics or not financial_line_items or (not market_cap):
        return {'score': 0, 'details': 'No data for second-level analysis'}
    latest_metrics = metrics[0]
    latest_financial = financial_line_items[0]
    if latest_metrics.price_to_book and latest_metrics.price_to_book < 1.2:
        earnings = [item.net_income for item in financial_line_items if item.net_income]
        if len(earnings) >= 3 and earnings[0] > earnings[1] > 0:
            score += 3
            details.append('Market pessimism vs improving fundamentals - second-level opportunity')
    if latest_financial.total_assets and latest_financial.total_debt:
        net_asset_value = latest_financial.total_assets - latest_financial.total_debt
        if net_asset_value > market_cap * 1.3:
            score += 2
            details.append('Hidden asset value not reflected in price')
    revenues = [item.revenue for item in financial_line_items if item.revenue]
    if len(revenues) >= 5:
        recent_decline = revenues[0] < revenues[1]
        historical_growth = revenues[-1] < revenues[-3]
        if recent_decline and historical_growth:
            score += 1
            details.append('Temporary setback in historically growing business')
    if latest_metrics.return_on_equity:
        historical_roe = [m.return_on_equity for m in metrics if m.return_on_equity]
        if len(historical_roe) >= 5:
            avg_roe = sum(historical_roe[1:]) / len(historical_roe[1:])
            if avg_roe > 0.15 and latest_metrics.return_on_equity < avg_roe * 0.6:
                score += 2
                details.append('Quality company at cyclical low ROE')
    return {'score': score, 'details': '; '.join(details)}

def analyze_market_psychology_indicators(metrics: list, market_cap: float) -> dict:
    """Marks' market psychology assessment"""
    score = 0
    details = []
    if not metrics or not market_cap:
        return {'score': 0, 'details': 'No psychology indicators'}
    latest_metrics = metrics[0]
    if latest_metrics.price_to_earnings:
        if latest_metrics.price_to_earnings < 8:
            score += 2
            details.append(f'Market pessimism: {latest_metrics.price_to_earnings:.1f} P/E')
        elif latest_metrics.price_to_earnings > 30:
            score -= 2
            details.append(f'Market euphoria: {latest_metrics.price_to_earnings:.1f} P/E')
    if latest_metrics.price_to_book:
        if latest_metrics.price_to_book < 0.8:
            score += 1
            details.append('Market pricing below book value - potential pessimism')
        elif latest_metrics.price_to_book > 3:
            score -= 1
            details.append('Market paying high premium - potential optimism')
    if latest_metrics.debt_to_equity and latest_metrics.debt_to_equity > 0.8:
        score += 1
        details.append('High debt company - potential contrarian opportunity')
    return {'score': score, 'details': '; '.join(details)}

def evaluate_asymmetric_opportunities(financial_line_items: list, market_cap: float) -> dict:
    """Marks' asymmetric risk/return evaluation"""
    score = 0
    details = []
    if not financial_line_items or not market_cap:
        return {'score': 0, 'details': 'No asymmetric data'}
    latest = financial_line_items[0]
    total_assets = latest.total_assets if latest.total_assets else 0
    total_debt = latest.total_debt if latest.total_debt else 0
    if total_assets > 0:
        net_assets = total_assets - total_debt
        if net_assets > market_cap * 0.8:
            score += 2
            details.append('Strong downside protection from asset backing')
    earnings = [item.net_income for item in financial_line_items if item.net_income and item.net_income > 0]
    if earnings and len(earnings) >= 3:
        best_earnings = max(earnings)
        current_earnings = earnings[0] if earnings[0] > 0 else earnings[1] if len(earnings) > 1 else 0
        if best_earnings > current_earnings * 1.5:
            normalized_value = best_earnings * 15
            upside_ratio = normalized_value / market_cap
            if upside_ratio > 2:
                score += 3
                details.append(f'Significant upside potential: {upside_ratio:.1f}x from normalized earnings')
    if latest.free_cash_flow and latest.free_cash_flow > 0:
        fcf_yield = latest.free_cash_flow / market_cap
        if fcf_yield > 0.1:
            score += 1
            details.append(f'Attractive FCF yield provides downside support: {fcf_yield:.1%}')
    return {'score': score, 'details': '; '.join(details)}

