    summary_lines = []
    key_indicators = {'CPIAUCSL': 'Core Inflation', 'UNRATE': 'Unemployment Rate', 'PAYEMS': 'Job Growth', 'GDPC1': 'GDP Growth', 'GS10': '10Y Treasury Yield'}
