                if buy_sell_ratio > 0.1:
                    market_implication = 'Strong insider buying - bullish signal'
                elif buy_sell_ratio < -0.1:
                    market_implication = 'Heavy insider selling - bearish signal'
                else:
                    market_implication = 'Balanced insider activity'
                return SmartMoneyIndicator(indicator_name='insider_trading', current_reading=buy_sell_ratio, historical_percentile=historical_percentile, signal_strength=signal_strength, market_implication=market_implication, asset_impact={'individual_stocks': buy_sell_ratio * 1.5})
