def paul_singer_strategic_decision(research_team: dict, legal_team: dict, activism_team: dict, event_driven_team: dict) -> dict:
    """Paul Singer's strategic decision framework"""
    details = []
    fundamental_value = research_team['score'] / 10
    governance_opportunity = legal_team['score'] / 8
    activist_potential = activism_team.get('activist_score', 0)
    event_catalyst = event_driven_team['score'] / 10
    overall_opportunity = fundamental_value * 0.3 + activist_potential * 0.35 + event_catalyst * 0.25 + governance_opportunity * 0.1
    campaign_complexity = assess_campaign_complexity(activism_team, legal_team)
    if overall_opportunity > 0.8 and activist_potential > 0.7:
        if campaign_complexity < 0.6:
            decision = 'Launch activist campaign'
            details.append('High-conviction activist opportunity with manageable complexity')
        else:
            decision = 'Complex activist situation - detailed planning required'
            details.append('High opportunity but complex campaign execution needed')
    elif overall_opportunity > 0.6:
        if event_catalyst > 0.7:
            decision = 'Event-driven position'
            details.append('Strong event-driven catalyst without activism requirement')
        else:
            decision = 'Moderate activist position'
            details.append('Moderate opportunity for value creation through activism')
    elif fundamental_value > 0.6 and activist_potential < 0.4:
        decision = 'Traditional value investment'
        details.append('Fundamental value present but limited activist opportunity')
    else:
        decision = 'Pass - insufficient catalyst potential'
        details.append("Insufficient catalyst opportunity for Elliott's strategy")
    if 'Management change' in activism_team.get('activist_catalysts', []):
        expected_timeline = '12-18 months'
    elif 'Strategic alternatives' in activism_team.get('activist_catalysts', []):
        expected_timeline = '18-24 months'
    else:
        expected_timeline = '6-12 months'
    return {'decision': decision, 'overall_opportunity': overall_opportunity, 'campaign_complexity': campaign_complexity, 'expected_timeline': expected_timeline, 'details': '; '.join(details)}

def analyze_hidden_asset_value(financial_line_items: list, market_cap: float) -> float:
    """Analyze hidden asset value opportunities"""
    if not financial_line_items or not market_cap:
        return 0
    latest = financial_line_items[0]
    if latest.total_assets and latest.total_debt:
        net_assets = latest.total_assets - latest.total_debt
        if net_assets > market_cap:
            hidden_value = (net_assets - market_cap) / market_cap
            return min(hidden_value, 1.0)
    return 0

def identify_business_optimization_opportunities(financial_line_items: list) -> float:
    """Identify business optimization opportunities"""
    margins = [item.operating_margin for item in financial_line_items if item.operating_margin]
    if len(margins) >= 3:
        recent_margin = margins[0]
        historical_best = max(margins)
        if historical_best > recent_margin * 1.3:
            return 0.8
        elif historical_best > recent_margin * 1.15:
            return 0.6
    return 0.3

def calculate_sum_of_parts_discount(financial_line_items: list, market_cap: float) -> float:
    """Calculate sum-of-the-parts discount (simplified)"""
    if not financial_line_items or not market_cap:
        return 0
    latest = financial_line_items[0]
    if latest.total_assets:
        estimated_sotp_value = latest.total_assets * 1.2
        if estimated_sotp_value > market_cap:
            discount = (estimated_sotp_value - market_cap) / market_cap
            return min(discount, 0.5)
    return 0

def analyze_executive_compensation_proxy(financial_line_items: list) -> float:
    """Analyze executive compensation alignment (proxy)"""
    fcf_vals = [item.free_cash_flow for item in financial_line_items if item.free_cash_flow]
    revenues = [item.revenue for item in financial_line_items if item.revenue]
    if len(fcf_vals) >= 3 and len(revenues) >= 3:
        fcf_growth = fcf_vals[0] / fcf_vals[-1] - 1
        revenue_growth = revenues[0] / revenues[-1] - 1
        if fcf_growth > revenue_growth:
            return 0.8
        elif fcf_growth > revenue_growth * 0.8:
            return 0.6
    return 0.4

def assess_operational_turnaround_potential(financial_line_items: list) -> float:
    """Assess operational turnaround potential"""
    margins = [item.operating_margin for item in financial_line_items if item.operating_margin]
    revenues = [item.revenue for item in financial_line_items if item.revenue]
    if len(margins) >= 3 and len(revenues) >= 3:
        margin_trend = margins[0] - margins[-1]
        revenue_stability = revenues[0] / revenues[-1]
        if margin_trend < -0.05 and revenue_stability > 0.9:
            return 0.8
        elif margin_trend < 0 and revenue_stability > 0.8:
            return 0.6
    return 0.3

def analyze_market_position_catalyst(financial_line_items: list) -> float:
    """Analyze market position improvement catalyst"""
    revenues = [item.revenue for item in financial_line_items if item.revenue]
    if len(revenues) >= 4:
        recent_decline = revenues[0] < revenues[1]
        historical_strength = max(revenues[2:]) > revenues[0] * 1.2
        if recent_decline and historical_strength:
            return 0.7
    return 0.4

def assess_management_change_potential(metrics: list, financial_line_items: list) -> float:
    """Assess management change potential"""
    management_score = assess_management_performance(metrics, financial_line_items)
    if management_score < 0.3:
        return 0.8
    elif management_score < 0.5:
        return 0.6
    return 0.2

def analyze_special_dividend_potential(financial_line_items: list) -> float:
    """Analyze special dividend potential"""
    fcf_vals = [item.free_cash_flow for item in financial_line_items if item.free_cash_flow]
    if fcf_vals:
        avg_fcf = sum(fcf_vals) / len(fcf_vals)
        if avg_fcf > 0:
            latest = financial_line_items[0]
            if latest.current_assets:
                return min(avg_fcf / (latest.current_assets * 0.1), 1.0)
    return 0.3

def assess_campaign_complexity(activism_team: dict, legal_team: dict) -> float:
    """Assess activist campaign complexity"""
    governance_issues = len(legal_team.get('governance_issues', []))
    activist_catalysts = len(activism_team.get('activist_catalysts', []))
    complexity_score = governance_issues * 0.15 + activist_catalysts * 0.1
    return min(complexity_score, 1.0)

class FyersTab(BaseTab):
    """Optimized Fyers Trading Tab for stock data streaming and API integration"""

    def __init__(self, app):
        super().__init__(app)
        self.tag_prefix = f'fyers_{id(self)}_'
        self.config_dir = self._get_config_directory()
        self.config_dir.mkdir(parents=True, exist_ok=True)
        self.credentials = {'client_id': '', 'pin': '', 'app_id': '', 'app_type': '', 'app_secret': '', 'totp_secret_key': '', 'redirect_uri': 'https://trade.fyers.in/api-login/redirect-uri/index.html'}
        self.BASE_URL = 'https://api-t2.fyers.in/vagator/v2'
        self.BASE_URL_2 = 'https://api-t1.fyers.in/api/v3'
        self._lock = threading.RLock()
        self.access_token = None
        self.is_connected = False
        self.websocket_client = None
        self.streaming_data = []
        self.max_streaming_rows = 1000
        self.previous_prices = {}
        self.is_paused = False
        self.session_start_time = None
        self.message_count = 0
        self.last_message_time = None
        self.current_symbols = ['NSE:SBIN-EQ', 'NSE:ADANIENT-EQ']
        self.current_data_type = 'DepthUpdate'
        self._last_table_update = None
        self._last_stats_update = None
        self.update_throttle_interval = 0.5
        self.load_access_token_on_startup()
        info('FyersTab initialized', context={'config_dir': str(self.config_dir)})

    def _get_config_directory(self) -> Path:
        """Get platform-specific config directory - uses .fincept folder"""
        config_dir = Path.home() / '.fincept' / 'fyers'
        return config_dir

    def get_label(self):
        return ' Fyers Trading'

    def get_tag(self, tag_name: str) -> str:
        """Generate unique tag with prefix"""
        return f'{self.tag_prefix}{tag_name}'

    def safe_add_item(self, add_func, *args, **kwargs):
        """Safely add DearPyGUI item with tag checking"""
        if 'tag' in kwargs:
            tag = kwargs['tag']
            if dpg.does_item_exist(tag):
                try:
                    dpg.delete_item(tag)
                except:
                    pass
        return add_func(*args, **kwargs)

    def safe_set_value(self, tag: str, value: Any):
        """Safely set value with existence check"""
        try:
            if dpg.does_item_exist(tag):
                dpg.set_value(tag, value)
        except Exception as e:
            warning(f'Error setting value for {tag}: {e}')

    def safe_configure_item(self, tag: str, **kwargs):
        """Safely configure item with existence check"""
        try:
            if dpg.does_item_exist(tag):
                dpg.configure_item(tag, **kwargs)
        except Exception as e:
            warning(f'Error configuring item {tag}: {e}')

    @monitor_performance
    def create_content(self):
        """Create the Fyers trading interface with error handling"""
        with operation('create_fyers_content'):
            try:
                self.cleanup_existing_items()
                self.add_section_header(' Fyers Trading Platform')
                if not FYERS_AVAILABLE:
                    dpg.add_text(' Fyers API not available!')
                    dpg.add_text('Install with: pip install fyers-apiv3')
                    dpg.add_text('Command: pip install fyers-apiv3')
                    return
                self.create_auth_panel()
                dpg.add_spacer(height=10)
                self.create_streaming_panel()
                dpg.add_spacer(height=10)
                self.create_data_viewer()
                info('Fyers tab content created successfully')
            except Exception as e:
                error('Error creating Fyers tab content', context={'error': str(e)}, exc_info=True)
                try:
                    dpg.add_text(f' Error creating interface: {str(e)}')
                    dpg.add_text('Please restart the application or check logs.')
                except:
                    pass

    def cleanup_existing_items(self):
        """Clean up any existing items with our tag prefix"""
        try:
            all_items = dpg.get_all_items()
            for item in all_items:
                try:
                    alias = dpg.get_item_alias(item)
                    if alias and alias.startswith(self.tag_prefix):
                        dpg.delete_item(item)
                except:
                    continue
        except Exception as e:
            warning(f'Warning during cleanup: {e}')

    def create_auth_panel(self):
        """Create authentication and token management panel"""
        with dpg.collapsing_header(label=' Authentication & Token Management', default_open=True):
            with dpg.group(horizontal=True):
                with self.create_child_window('credentials_panel', width=400, height=320):
                    dpg.add_text('Fyers API Credentials')
                    dpg.add_separator()
                    self.safe_add_item(dpg.add_input_text, label='Client ID', default_value=self.credentials['client_id'], tag=self.get_tag('fyers_client_id'), width=200)
                    self.safe_add_item(dpg.add_input_text, label='PIN', default_value=self.credentials['pin'], tag=self.get_tag('fyers_pin'), password=True, width=200)
                    self.safe_add_item(dpg.add_input_text, label='App ID', default_value=self.credentials['app_id'], tag=self.get_tag('fyers_app_id'), width=200)
                    self.safe_add_item(dpg.add_input_text, label='App Type', default_value=self.credentials['app_type'], tag=self.get_tag('fyers_app_type'), width=200)
